var PRESET_DESCS ={"重瞳":"运功之际，双瞳重叠微旋，内墨外曜，幽芒如神明俯瞰尘寰。敌方之玄奇阵法、阴诡暗器、迷魂音煞尚未近身，其运转节点与生克死穴早已在重瞳中被层层剥解得一览无余；持有人举手投足尽破敌手后招，同时诸般奇门杀手信手拈来、重叠爆发，威力全额齐放，惊艳绝伦。","天凤血":"气机激荡之际，心窍深处传出穿云裂石般的清越凰鸣，眼波流转带出赤金炽芒。持有人出手自带一股焚尽劫灰的桀骜气魄；哪怕此前曾遭挫折欺凌、重伤垂死，只要一线生机不绝，重返战场之时气象必脱胎换骨，真气愈发炽烈雄浑，宛若神凰傲立九天。","飞天御剑流":"崖底残卷所得，专练拔刀速度，修至大成可于瞬息间拔刀斩出，刀光未至人已中招。","九头龙闪":"崖底残卷所得的奇绝之术，能从九个方向同时发动攻击，防不胜防，一击九杀。","汉宫秋":"运转时真气带有秋日肃杀之意，能无声无息剥夺周遭生机。","桃花扇":"掌风如桃花飘落，看似柔美，实则掌力能透过肌肤直接震碎五脏六腑。","梧桐雨":"身法极度空灵，移动时犹如细雨穿林，无声无迹，瞬息千里。","天蛟换骨":"天下第一锻骨筑基法。强行拔高生理资质上限，把平庸体质重塑为武道天才；圆满可达成肉身先天无漏。","长鲸吞海":"蓬莱最高绝学。真气总量远超同境数十倍，丹田如无底海眼，可强行吸纳敌方内力转化为己用。","仙人抚我顶":"沈逍自创掌法。一掌拍下附带千万道虚影，令人无法判断真实进攻轨迹。","结发受长生":"沈逍自创横练。可大幅度延缓衰老、驻颜美容，保持身体的全盛姿态。","天魔大化":"天魔阁镇派先天真功。以魔气化形、噬人内元；修至极处可把对手的真气与血肉一并纳入己身。","流云掌":"二品掌法。掌势如云舒卷、绵密不绝，善借对方力道；起手不快，胜在后劲不断。","养元桩":"二品横练。以桩功养元固本，久立不疲、耐打耐饿；练成者皮肉如牛皮，寻常刀剑难入。","破石拳":"三品拳法。族中祖传的硬拳，一拳打在石上能裂开纹路；招式朴素，胜在踏实。","活气诀":"三品内功。调息活气、去淤通络，练久了气息绵长，是寒门子弟最普通的入门内功。","蜀中散手":"三品拳法。蜀中街头打出来的散手，讲究先下手、打要害，不好看但管用。","真龙皇极功":"大凉皇室核心内功。真气霸道呈明黄，运转时万法不侵，能强行冲散品级低于自身的异种真气，但对肉体经脉负荷极大。","镇国九鼎拳":"太祖敖海墨晚年融汇百家所创。出拳时真气凝结如青铜巨鼎，拳意与大凉国运相连；在皇城或大凉军阵中施展，威力翻倍。","临川剑法":"文华书院入门剑法。剑招中正平和，适合初学者打磨根基。","自华决":"文华书院中阶内功。腹有诗书气自华，真气运转带有儒家浩然之意，平稳绵长。","王将军剑诀":"文华书院中阶剑法。共分两式，一式紫电行如霹雳、一式青霜轻灵卓越，两式互为首尾。","万物情理":"源自白泽血脉的先天神通，演武时思绪澄明，手眼身步的生涩窒碍渐次理顺，化繁为熟。","粗浅桩功":"以站桩、拍打和负重打熬筋骨的粗浅横练，招式朴素，市井武师多有传授。","地躺拳":"滚翻起落、贴地出拳的粗浅防身拳脚，重在跌扑间护住要害、寻隙还手。","定北游":"玉蝉留存着前世所见的功诀。凝神回想时，功诀在微光里逐字显出，伴着蝉鸣落成纸上的残页。","大梦神功·残篇":"从前世梦中带回的零落功诀，行气总纲尚存，后文却多有断缺。持卷吐纳时逐句辨认，纸上字迹与前世记忆相互印证。","小周天引气术":"凉州小世家传习的入门内功，循经导气、周流往复，吐纳平缓，适合用来打稳初习武道的根底。","杏花微雨燕双飞":"六扇门秘传的轻灵刀法，出刀如细雨随风、双燕斜掠，招式绵密迅疾，近身时刀锋交错，寻隙而入。","潜龙勿用诀":"大凉大内所藏的养气心法，气机深沉若渊龙潜伏，行功时内息内敛无形，外人极难窥探虚实境界。","分经错骨手":"虎豹房秘传的擒拿技，专寻人体百骸筋络与骨节空隙发力，触之即错，扣之即断，利于近身制敌。","呢喃诗章":"月光照入灵台，浑噩岁月里积下的寒暑、饥苦与茫然，开智后渐渐化作心中低回的私语。那些未曾言说的感触，伴着脑海中的呢喃连成诗句。每次回想，熟悉的字句里又会显出从前未曾读懂的意味。","木叶瞬身步":"三品轻功。将真气骤然灌注足底爆发短途疾冲的步法，胜在起落突然。","木叶旋风腿":"三品腿法。借腰胯拧转之力腾空横扫的刚猛腿功，专攻敌手下盘与胸胁。","灼幽烈阳":"先天神通。引动体内九尾天狐的本源妖火化为赤金烈阳焰衣披覆周身，兼具狂暴巨力、极速愈伤与焚山煮海的赤金妖火攻伐。","猛虎硬爬山":"二品拳法。阳洛城武馆流传的刚猛拳路，发力短促凶悍，讲究贴身硬打、一拳接一拳毫不停歇。","壮血吞气功":"二品内功。气血与真气并重的内家法门，运转时气血滚烫，极耐拳脚重击。","铜皮铁骨功":"三品横练。市井扎实的外门硬功，练至圆满后皮肉紧实如熟牛皮，寻常钝器难伤。","烈虎下山":"二品拳法。阳洛城武馆流传的刚猛拳路，发力短促凶悍，讲究贴身硬打、一拳接一拳毫不停歇。"};
var PRESETS ={"镜中议事":{"g":"男","level":"三境明气","faction":"无门无派","loc":"蜀州·蜀州旧居","job":"蜀州普通人家的孩子（镜中议事的召集人）","bg":"你是个带着前世记忆降生的胎穿者。这一世你投生在蜀州城一户普通百姓家里，爹在街面铺子里当伙计，娘在家给人做针线活，一家人勉强糊口，根本没钱供你拜师学艺。你出生那天夜里，一面巴掌大的青铜古镜莫名其妙掉在自家门前台阶上，镜背刻着古怪云纹，镜面灰蒙蒙的照不出人影；爹娘当是件不值钱的破铜烂铁，便留给你当了随身带的小玩意。你这辈子的练武资质实在平庸，靠着街头偷学来的粗浅把式苦练到十六岁，才堪堪达到三境明气。直到今天夜里，你像往常一样把古镜放在枕头边睡下，迷迷糊糊间一阵天旋地转，再睁眼时，竟发现自己站在了一片无边无际的深灰空间里。与此同时，这面无名宝镜的底细也自然而然地浮现在你脑海中：每逢月初，宝镜便能隔空摄来几道神魂聚在镜中议事；在这片镜界里，管你是江湖宗师还是再世神魔，一切真气武功统统使不出来，所有人的样貌、身形和嗓音都被浓重的灰雾遮得严严实实；唯独身为宝镜主人的你，非但能给自己随便捏造伪装，还能一眼看穿在场被拉进来的那三个人到底是谁——左边那个站在宫灯虚影下、气度深沉的年轻男子，竟然是大凉当今圣上、更启帝敖澜；右边那个立在山巅、手按剑柄的冷峻青年，是武林盟少盟主、人榜第一的【小剑神】秦珏；而在道观蒲团旁拢着袖子左顾右盼的少女，则是凉州纯阳宗的小师妹风絮。","money":"铜钱五百文","gear":"无名宝镜（巴掌大，青铜边框，照不出人影只映深灰；每月一次可摄人神魂入镜议事）","skillType":"preset","skill":"自得奇功·二品横练《养元桩》、自得奇功·三品拳法《蜀中散手》","profs":"皮毛、粗通","scene":"空旷死寂的深灰镜界里，四周飘浮着无数面映照山河景象的铜镜。被强行拉进来的三个人各自退开几步，全神戒备：宫灯下的更启帝敖澜负手站在阴影里，不动声色地打量着四周；孤峰上的秦珏试着提聚真气未果，手指依然死死扣在剑柄上；纯阳宗的风絮则缩着脖子左右张望，一副随时准备拔剑的模样。在他们仨眼里，在场所有人包括坐在主位上的你，全都裹在灰雾里看不清深浅。足足沉默了好半晌，还是更启帝敖澜最先沉不住气，被灰雾掩去本音的低沉嗓音在空间里响起：「不知哪位前辈施展通天手段，将我等神魂摄来此处？还请现身一叙。」随着他话音落下，三道试探的目光齐刷刷落在了主位上的你身上。你心里清楚自己不过是个三境明气的穷小子，可眼下借着这面古镜的威势，该如何开口镇住这三位来头吓人的家伙，全看你接下来怎么编了。","age":"16"},"重瞳遗孤":{"g":"男","level":"三境明气","faction":"无门无派","loc":"禹州·采药山道","job":"禹州破落宗族之子（被夺去至尊骨的遗孤）","bg":"你生在禹州一脉早已败落的武道旁系宗族，族中三代未曾出过一个开窍境的人物。偏偏你降生那夜天生异象：胸膺间一块奇骨金纹密布，双目之内更是双瞳并蒂。族老见之老泪纵横，断言这是千古罕见的【至尊骨】与【重瞳】同降一人。你三岁能举石臼，五岁气血自生，全族省吃俭用将仅有的汤药尽数喂给了你。谁料七岁那年寒冬，阳洛城沈氏本家忽派马车登门，以「接往宗家延请名医调理经脉」为名将你骗入内宅密室。那一夜风雪凄厉，主刀的术者漠然说着「此等神骨生在泥腿子身上未免暴殄天物」，活生生剖开你的胸膛，剜走了那块天生至尊骨。待你被像死狗般丢回乡下祠堂时，胸口只余一道深可见骨的血疤；唯有那双被血泪糊住的重瞳，因无人识货而侥幸留存。自此你元气大伤、根基崩毁，宗家供奉彻底断绝，旁系亲族亦视你如瘟神。九年光阴流转，你独自栖身于塌了半边的荒废祖祠，靠打短工、进山采药勉强熬至三境明气；而九年前密室里那声高高在上的「少主」，你一日也未曾忘却。","money":"铜钱一百二十文","gear":"断刃柴刀（不入流）、一床旧被","skillType":"preset","skill":"自得奇功·三品拳法《破石拳》、自得奇功·三品内功《活气诀》、自得奇功·先天神通《重瞳》","profs":"粗通、粗通、圆满","scene":"今日一早，你背着竹篓替镇上药铺进山采药，行至狭窄的断崖山道时，迎面撞上了一队鲜衣怒马的护卫。居首那名十六岁的锦袍少年外披雪白貂裘，腰悬寒铁雁翎刀与一枚刻着「沈凌霄」三字的羊脂玉牌，胸膛衣料下隐隐透出一丝熟悉的浑厚金霞。他的视线越过马头，饶有兴致地停在你那双异于常人的眼眸上。在他马后左右，一左一右紧随着两名气息如渊的六关气海供奉——提熟铁齐眉棍的破戒恶僧柴猛，以及按着厚背朴刀的薛崇。薛崇那张蜡黄冷漠的脸你死也不会认错，九年前那个雪夜，正是这双手将七岁的你抱上了取骨的马车。沈凌霄居高临下地勒住马缰，指尖轻轻摩挲着自己胸口的衣襟，语气轻慢得像在估量一件漏网的货物：「那晚光顾着取骨，倒忘了你这泥腿子脸上，还长着一双挺有意思的眼睛？」前路已被沈家护卫尽数堵死，你背后是百丈深涧，手里只有一柄崩了刃的旧柴刀。","age":"16","lockGender":true},"退婚觉凤":{"g":"男","age":"21","level":"二境筑基","faction":"无门无派","loc":"禹州·阳洛城","job":"阳洛城宗族子弟","bg":"更启年间，禹州阳洛城中宗族林立。你本是城中声名鹊起的少年英杰，年不过十八便以雄浑真气贯通面部七窍、踏入四境开窍，更与城中望族纳兰氏那位才情斐然、古灵精怪的嫡长女纳兰清浅订有指腹婚约。然而三年前，你体内原本奔涌的真气骤生阻绝，再难感应天地间的游离气机，周天溃散之下，一身修为一路滑跌回二境筑基，自云端跌落泥淖，受尽族人与市井的冷眼非议。恰在那一年，素日里惯爱与你打趣说笑的纳兰清浅忽然当众登门，冷着脸奉上一纸退婚书当场断义割席，随后便远赴中天峰拜入五岳剑派。世人与你自己皆以为武道根基尽毁，却不知这三年的修为倒退，实则是你骨血深处隐伏的上古天凤血在破壳苏醒前必经的潜伏之劫。","money":"铜钱一百五十文","gear":"磨损粗布劲装、粗铁护腕、草鞋","skillType":"preset","skill":"自得奇功·三品拳法《破石拳》、自得奇功·三品内功《活气诀》、自得奇功·先天神通《天凤血》","profs":"粗通、粗通、圆满","scene":"三年之期已满。正午的冬日微风拂过偏院残破的旧演武场，你双拳缠着磨破见线的粗布带，孤身一人立在青石板上如常演练桩功。挥拳收势的刹那，心口骨髓深处毫无征兆地涌出一股前所未有的融融暖意，干涸沉寂了整整三载的周天经络间，骤然燃起一缕微弱却至纯至阳的赤金气感。一声清越似穿云裂石的凰鸣自胸骨深处隐隐震颤，脚下方寸之地的枯叶被无形热浪荡开半寸。你的修为虽仍停在二境筑基，可那缕沉睡初醒的凰火，已如久旱逢甘霖般缓缓流向四肢百骸。"},"玉佩天魔":{"g":"男","level":"三境明气","faction":"无门无派","loc":"宸州·商户宅院","job":"宸州小富商之子（天魔阁大天魔的记名弟子）","bg":"你是宸州天凉城一户绸缎商家的独苗，家里在城中有两间铺面，日子过得颇为宽裕。你打小就做着仗剑江湖的美梦，奈何练武的天分实在稀松平常，老爹花大价钱给你请过三个武馆教头，个个都摇头说你经脉松散、不是练武的材料，苦熬到十八岁也才勉强迈进三境明气。半个月前，你在西市鬼市的地摊上花三十文铜钱买了一块黑漆漆的旧玉佩，图个好看便挂在了腰上。谁知当天夜里一闭眼，你竟在睡梦里掉进了一片尸山血海，血海正中站着个穿黑袍的魁梧汉子。那人自称林昊，竟是六十年前灭梦之战里与赤血武王同归于尽的天魔阁主、抱丹神魔【大天魔】！他藏在玉佩里的一缕残魂本想直接吞了你的魂魄夺舍重生，没承想你练武虽然废柴，天生的神魂却壮得像块生铁，反把他的残魂震得够呛。夺舍不成，这老魔头倒也干脆，发现你的体魄恰好能承受天魔阁绝学《天魔大化》的反噬，当场跟你谈了笔买卖：他做你的师父，把天魔阁的无上绝学教给你；等你将来练成气候，得替他找齐天材地宝重塑肉身。","money":"白银三十两、绸缎铺月例二两","gear":"旧玉佩（林昊残魂所寄）、家中短刀一把（三品）","skillType":"preset","skill":"自得奇功·二品掌法《流云掌》、自得奇功·二品横练《养元桩》、自得奇功·先天真功《天魔大化》","profs":"皮毛、皮毛、皮毛","scene":"昨晚睡梦里，林昊终于肯松口，把《天魔大化》总纲的第一段行气口诀传给了你。今早天刚亮你便爬起来，躲在自家后院的角落里偷偷照着口诀运气。才刚运转了一个周天，你便觉得丹田里滚过一股黑沉沉的热流，随手朝着院心那口冻了冰的青石大水缸虚推一掌——只听「咔嚓」一声脆响，五步外的大水缸连冰带石裂开了一道长缝。你正盯着自己的手掌发愣，前堂忽然传来老爹叫你去对账的喊声。等你在饭桌上坐定，老爹一边拨着算盘，一边随口嘀咕了一句：「这两天西市那边不太平，昨儿店里来了几个穿玄青劲装的怪人，绸缎一匹没买，光拉着伙计打听这几条街上谁家小子前阵子在鬼市买过旧玉器……你平日少往鬼市那种乱地方跑。」你端着粥碗的手微微一顿，腰间那枚暗色玉佩贴着皮肉，隐隐传来林昊残魂若有若无的一声冷笑。","lockGender":true},"仙缘偶得":{"g":"男","level":"三境明气","faction":"无门无派","loc":"蓟州·农家村落","job":"农家子弟（沈逍的记名弟子）","bg":"你是蓟州乡下山村里一户庄稼人的二儿子，从小跟着老爹下地干活、进山砍柴，除了一把子庄稼汉的傻力气外啥也不会。三天前你挑着两担柴火去城外换盐，路过山涧时，撞见个穿白袍的道人站在水边看鱼。那道人随手一挥袖子，哗哗流淌的溪水居然倒卷着飞起三尺高，等水落回去，溪里的鱼虾连蹦都没蹦一下。你当时就看傻了眼，扁担滑下来砸了脚面都不敢吱声。那白衣道人回头瞧见你这副憨样，笑眯眯地问你想不想学这本事；你挠着后脑勺实话实说，要是跟神仙走了，家里的几亩薄田就没人帮爹娘种了。道人听罢哈哈大笑，走过来伸手在你头顶轻轻拍了一下。你只觉得一股清凉的气流直灌进肚子里，原本空空荡荡的下腹轰隆一声像是炸开了一口深井，眨眼间便跨过了旁人苦练十来年的门槛，成了三境明气的武人。道人自称沈逍，说路过北地顺手收你当个记名徒弟，随手丢给你一枚白贝壳，又在泥地上用树枝划了三门功法的口诀让你死记硬背下来，留下一句「三年后要还活着，就拿这贝壳去南海蓬莱三岛找我」，转眼便没了影踪。回村之后，你怕吓着二老，对谁也没敢吭声。","money":"铜钱八百文、碎银一两","gear":"柴刀一把、粗布短褐、沈逍留下的贝壳信物","skillType":"preset","skill":"自得奇功·先天真功《长鲸吞海》、自得奇功·后天掌法《仙人抚我顶》、自得奇功·后天横练《结发受长生》","profs":"皮毛、皮毛、皮毛","scene":"回村这三天，你每天半夜都缩在柴房里，照着死记下来的《长鲸吞海》口诀瞎琢磨。这门神仙功夫霸道得很，你身上的力气一天比一天大，可没师父在旁教你怎么收放力道，肚子里那股真气就像脱了缰的野牛一样乱窜。到了今天下午，你在村头晒谷场上干活，顺手想去挪一挪那块往常两个壮劳力都推不动的青石碾子。谁知你刚一憋气使劲，双臂真气猛地蹿了出来，几百斤重的大石碾子竟被你一把掀飞出去老远，「轰」的一声砸进隔壁水田，把泥巴田埂都砸塌了一大截。正在田里干活的邻家老叔吓得一屁股坐在泥水里，指着你扯开嗓子直喊「妖怪」；偏偏这时候村口大路上正有几名挎刀背剑的江湖客路过歇脚，听见这动静，几双眼睛顿时齐刷刷地盯上了晒谷场中央手足无措的你，而自家院门里也传来了爹娘急匆匆跑出来的脚步声。","lockGender":true},"六扇青绥":{"g":"男","level":"五境八关_一关开","faction":"宸州 - 六扇门","loc":"宸州·回京荒庙","job":"六扇门青绥","bg":"你出身宸州寻常百姓家，自幼熟读《大凉律》，见惯了街市上的不平事，及冠后便投效六扇门。你虽非门主诸葛我座下的四名亲传弟子，却凭着断案的机敏与一身不要命的硬功夫，三年里从一名巡街捕快步步擢升。数日前围剿悍匪时，你于刀光血影中临阵破入五境八关第一关，诸葛我亲授青绥，同僚皆道你前途无量。门中上下，你与三师兄明轻罗最是投契——这位三师兄常年白衣胜雪、折扇不离手，偏又是个逢赌必输的臭棋篓子，三年间你们不知在天凉城的酒肆里抵足喝空了多少坛烈酒。","money":"白银五十两","gear":"二品双刀、六扇门令牌","skillType":"preset","skill":"二品内功《正气歌》、一品刀法《杏花微雨燕双飞》、一品横练《千磨万击还坚劲》","scene":"你与二师兄伍凌、三师兄明轻罗奉命押解一名要犯回京，连日赶路，夜宿在官道旁的荒庙里。半夜起身添柴时，你无意间转过坍了一角的偏殿，正撞见明轻罗背对着门解开发髻、褪去束胸外衫——那个三年来与你勾肩搭背、划拳行令的好兄弟，月光下散落一肩乌发，眉眼清艳，竟是个货真价实的女子。听见脚步声，她猛地揽衣旋身，铁骨折扇已抵在指间，眼底寒芒乍起；待看清来人是你，那股杀机才僵在脸上，化作满面羞恼与戒备。外间庙廊下，古板耿直的二师兄伍凌正抱刀守夜，脚步声近在咫尺。"},"佛恋红尘":{"g":"男","level":"五境八关_一关开","faction":"禹州 - 大菩提寺","loc":"禹州·山脚茶棚","job":"大菩提寺佛门弟子","bg":"你生在禹州富庶商贾之家，自幼不喜算盘账册，偏爱舞枪弄棒，又生得眉清目秀、唇红齿白。父母见你向武之心甚坚，便备下重礼送你入大菩提寺修行。永尘方丈念你心诚，收为寺中弟子，赐法号「恒明」。入寺三载，你虽剃度披衣，心性却依旧烂漫跳脱，对山门外的花花世界满怀好奇——师兄们枯坐参禅时，你偷溜去后山看流云飞鸟；演武堂练棍时，你也总爱把古朴招式耍得花团锦簇。方丈见了常摇头笑叹你「六根未净，尘缘尚浅」，却从不苛责你这份赤子心肠。前日你水到渠成破入五境八关第一关，方丈便唤你至殿前，温言令你下山历一回红尘。","money":"白银五百两（家中接济）","gear":"二品铁棍、菩提念珠","skillType":"preset","skill":"二品内功《罗汉心经》、一品横练《金钟罩》、一品棍法《疯魔杖法》","scene":"晨课钟声甫落，你辞别方丈与诸位师兄，背起铁棍踏出山门。古寺的袅袅檀香渐行渐远，阳洛城外的官道上车马喧阗，处处是叫你瞧不够的市井烟火。行至山脚一处简陋茶棚歇脚时，角落长凳上已独坐着一名女子。她生得极美，眼波流转间笑意盈盈，大白天却将一件宽大的厚斗篷裹得严严实实。见你落座，她掩唇轻笑，主动凑过来搭话，说是赶路遇了山雨、衣衫湿透，向你讨个火折子烘一烘手。你老老实实递过火折子，她接过时，微凉的指尖似有若无地擦过你的手背，斗篷下隐隐透出一缕甜腻的暖香。你耳根发烫，忙低头诵了一声佛号；殊不知眼前这笑语嫣然的女子，正是魔门第一大派血神宫的极乐使温软香。她前夜在禹州与仇家搏杀，不仅身受内伤，更因强行催动奇淫合欢散而遭药力反噬，此刻宽大斗篷下的衣衫早已破损不堪，全凭一口真气勉强压着翻腾的邪火。她一眼瞧出你这大菩提寺的小和尚身怀未经人事的精纯佛门元阳，既是压制反噬的绝佳炉鼎，又是眼下躲避正道搜捕最好的护身符，当即便支着下巴笑吟吟地赖上了你，说前路不太平，非要与你这位小师父结伴同行不可。","lockGender":true},"遗孤复仇":{"g":"男","level":"五境八关_一关开","faction":"岳州 - 武林盟","loc":"岳州·武林盟总舵","job":"武林盟传武堂弟子","bg":"你本是锦州一处小门派的子弟。幼年那场大雪夜里，虎豹房以「通敌乱国」的罪名破门而入，满门上下数十口尽数倒在血泊中，唯有你被恰好路过的武林盟弟子从死人堆里救出。盟主秦白见你可怜，将你托付给传武堂主沈玉飞收为弟子。沈玉飞平素懒散嗜酒，唯独教你习武时极为用心，将一身本领倾囊相授；堂中年纪相仿的师姐端木凝更与你自幼相伴，一晃十余载，情同手足。数日前你破入五境八关第一关，当年的灭门血债在心底压了十几年，如今手里的剑终于有了几分讨债的分量。","money":"白银三十两","gear":"二品长剑、武林盟弟子令","skillType":"preset","skill":"一品指法《罚恶剑指》、一品横练《八风不动罡》、一品内功《大衍周天功》","scene":"正月里的岳州武林盟总舵张灯结彩，二十年一届的「大凉终极厨神大赛」定于今年在总舵开席。三教九流的食客与各派名宿陆续登门，你被指派去帮着搭台布席、巡查外院，忙得脚不沾地；偏偏端木凝如鱼得水，一早便钻进后厨试菜备料，嚷着要在天下名厨面前露上一手。午后你正扛着一摞青花碗碟穿过回廊，师父沈玉飞拎着酒葫芦迎面晃了过来。他灌了一口酒，拦住你压低声音道：「这届厨神大赛水深得很，有人想借着热闹掀桌子，你警醒着些。」顿了顿，他浑浊的酒眼里掠过一丝冷意，「朝廷那三家这次都递了帖子——六扇门、武备司，还有虎豹房的人，这两日就会到。收好你的脾气，别让人抓了把柄。」话音落下，他拍了拍你的肩头，晃着酒葫芦径自远去，只留你抱紧怀中的瓷碗，指节捏得发白。"},"书院剑客":{"g":"男","level":"五境八关_一关开","faction":"锦州 - 文华书院","loc":"锦州·镜湖府","job":"文华书院内门弟子","bg":"你出身锦州书香门第，自幼饱读诗书，亦好击剑之术。入文华书院求学后，你在经义策论上才思敏捷，剑法进境亦是不俗，不多时便被院长许墨然收入内门，前些日子更顺利破入五境八关第一关。书院中有一名唤作孔萱的小师妹，天生一头五色异发，性子怯懦寡言，常受外舍学子疏远议论。你见她孤单，平日便多有照拂：有人在廊下嚼舌根，你出言挡回；演武场上无人与她拆招，你便多陪她走几趟剑；连膳堂放饭时也常替她留个清静座位。小师妹嘴上笨拙，每回见你走近，低垂的眼眸总会悄悄亮起几分。","money":"白银四十两","gear":"二品文剑、书箱","skillType":"preset","skill":"二品内功《自华决》、一品剑法《君子六艺剑》、一品轻功《大道之行也》","scene":"时值更启二年正月初五，镜湖畔春寒未退，文华书院上下已开始张罗二月初二的「锦州诗剑会」，邀集天下才子剑客的泥金帖子正一封封发往各州。午后你在斋舍中研墨润笔，准备参会的诗稿，门扉被轻轻叩响，孔萱抱着一摞整理齐整的书卷怯生生地迈进门槛。她将替你誊抄好的策论放在案头，手指绞着衣角，小声说二月比剑时想来台下替你捧剑。你刚温言应下，院外忽然传来一阵激烈的喧哗——几名同窗正围着刚贴出的参会名录争执不休，隐约听见有人拍案怒斥：「文华书院的诗剑雅集，怎会混进东瀛武人的名字？！」"},"道门师弟":{"g":"男","level":"五境八关_一关开","faction":"岳州 - 真武派","loc":"岳州·真武派后山","job":"真武派内门小师弟","bg":"你本是岳州山野间的弃婴，幼年被下山云游的真武派掌教冲霄真人捡回山中。真人见你心性纯良、根骨清奇，便将你收作关门小弟子。真武派乃道门太极正宗，历经六十年前灭梦之战的创伤后，门风愈发恬淡平和。你在山上辈分最小，师兄师姐素来待你极宽厚，尤以清茗师姐最为温婉体贴，你自幼的吐纳桩功与剑法路数，大半都是她手把手教出来的。数日前你破入五境八关第一关，本想寻师姐讨教新招，却不想在今夜的后山撞破了她藏在道袍下的秘密。","money":"白银二十两","gear":"二品木剑、真武派弟子令","skillType":"preset","skill":"二品内功《太极养气功》、一品剑法《回风扶柳剑》、一品横练《棉体》","scene":"后山夜寒，松涛阵阵。你在崖下演练完一趟《回风扶柳剑》，收剑吐纳时，忽见峭壁边缘坐着一道熟悉的青色道影。清茗师姐正独自对着月色出神，掌心托着一枚温润白玉佩——借着清冷月华，你分明认出那玉佩上盘绕的是大凉皇室独有的五爪蛟龙纹。似是察觉到你的气息，清茗浑身一震，右手骤然按上剑柄；待转头看清是你，她眼底罕见地掠过一丝惊惶，随即化作深不见底的挣扎。山风吹乱了她的鬓发，良久，这位平日里连说话都温声细语的师姐才缓缓起身，将龙纹玉佩拢入袖中，背过身哑声道：「小师弟……今夜之事，万不可向掌教与大师兄提起半句。」你张口欲问，却见她单薄的肩头在月下微微颤抖。","lockGender":true},"戏班武生":{"g":"男","level":"五境八关_一关开","faction":"蓟州 - 众志盟","loc":"蓟州·梨园班驻地","job":"众志盟梨园班武生","bg":"你出身蓟州临海城的寒苦之家，幼年流落街头时被众志盟梨园班收留。班主荀满楼见你筋骨柔韧、嗓音亮堂，便收你做了入室弟子，专攻武生行当。你与师姐梅青裳自幼在一处压腿劈叉、同台唱戏，可谓两小无猜。你在戏台上唱惯了忠臣良将，台下也是一副嫉恶如仇的侠义热肠；梅青裳却是个彻头彻尾的戏痴，常拉着你在后台对枪排戏到三更半夜，你嘴上嫌她疯魔，手里的花枪却从没慢过半拍。开春前后，北疆金月部落叩关劫掠的急报传至蓟州，众志盟传令各堂口选派精锐北上燕州助战，刚破入五境八关第一关的你与梅青裳当即递了请缨帖。","money":"白银二十五两","gear":"二品长枪、戏班行头","skillType":"preset","skill":"一品枪法《霸王卸甲枪》、一品腿法《飞燕回翔腿》、二品内功《梨园靠子功》","scene":"临海城的夜风裹着海腥与北地的霜寒，吹得戏楼檐角的铁马叮当作响。明日一早便要启程奔赴燕州边关，你正在梨园后台收拾行囊、捆扎戏箱。一旁的梅青裳却还没卸去旦角靠旗，正对着铜镜一遍遍挽着枪花，口中念念有词地哼着戏文里的杀敌唱段。忽听「啪」的一声轻响，她反手收枪立定，借着昏黄的烛火转头看向你，眼底亮得惊人：「师弟，平日里咱们在台上唱了千百回的精忠报国、替天行道——你说明日出了这临海城，咱们这一去，可算真正唱上这一出了？」","lockGender":true},"大漠遗孤":{"g":"男","level":"五境八关_一关开","faction":"凉州 - 大梦教残部","loc":"凉州·大漠宿营地","job":"大梦教铁面尸王荆南柯副手","bg":"你是西域大漠深处的孤儿，自记事起便在大梦教残部的营帐间摸爬滚打。教中上下皆是刀口舔血的亡命徒，唯有铁面尸王荆南柯拿你当活人看待。她原是湘西赶尸派传人，满门被朝廷虎豹房屠尽后远遁大漠，兴许是见你孤苦如当年的自己，便将你留在身边做了副手，亲授《铁尸冥气》与控尸之术。这些年你们主仆二人在教中相依为命，你替她打理尸傀、巡守营盘，对紫气龙王慕容铎那副自诩前朝皇裔的高傲做派素来嗤之以鼻。在你心里，什么「众生入梦」、什么复国霸业皆是虚妄，只要荆南柯还在，你手里的铁链便替她拦下一切暗箭。","money":"白银十五两","gear":"二品锁链、铁面具","skillType":"preset","skill":"后天内功《铁尸冥气》、一品奇术《控尸锁链》、先天真功·残卷《大梦神功》","scene":"大漠寒夜，狂风卷着沙砾拍打驼毛帐篷。你刚破入五境八关第一关不久，正在篝火旁替荆南柯守夜。帐中火光摇曳，荆南柯摘下脸上那副终年不离身的青铜铁面，露出一张毫无血色的苍白面容。她将一卷刚从总坛送来的密令丢进火堆，看着羊皮卷在火舌中蜷曲焦黑，冷声道：「下月西域大雪山举办二十年一度的无上法会，活佛旦增给中原各派都发了请帖。赫连博山坐不住了，打算借着大雪山『善恶轮回』的由头在法会上动手脚。」你闻言皱眉，代教主赫连博山每回兴风作浪，推上去当炮灰的总是你们这些外围部众。荆南柯重新扣上铁面，声音隔着青铜面甲显得沉闷而冰冷：「慕容铎那老匹夫最近背着总坛，在跟西域几股大马匪暗中勾连。这几日你带人去盯紧他的动向，别让人卖了我们还替他数钱。」"},"浪人刀客":{"g":"男","level":"五境八关_三关生","faction":"无门无派","loc":"海州·庙会街市","job":"无门无派浪人刀客","bg":"你是海州山野里长大的孤儿，无门无派，亦无师承。幼年进山采果时不慎失足坠崖，非但大难不死，反在崖底一处坍塌的古洞里捡回一条命。洞中枯骨旁留有一柄一品名刀「雪走」，以及两卷泛黄残篇——后天刀法《飞天御剑流》专攻拔刀术的瞬息极速，一品奇术《九头龙闪》则能于呼吸间连出九刀、封死四方退路。你在洞底靠啃食一株异果熬过数日，出谷后方知那果子名为「明目果」，自此你双目清明异于常人，旁人言语间若有心虚扯谎，气机微澜与眼底闪烁在你眼里皆无所遁形。十余年晃荡下来，你已修至五境八关第三关，一人一马游走海州，不拜山门、不受管束，有酒便饮，见不平便拔刀。","money":"白银十两","gear":"一品名刀雪走、三品老马「老伙计」（虽老但极为聪慧、极通人性）、一品天材地宝明目果（已服用，可看穿谎言与隐瞒）","skillType":"preset","skill":"自得奇功·后天刀法《飞天御剑流》、自得奇功·一品奇术《九头龙闪》","scene":"正月里的海州庙会人声鼎沸，海风里混着煎饼与脂粉的香气。你牵着通人性的老马「老伙计」，嘴里叼着一串糖葫芦在摊位间信步闲逛，腰间那柄削铁如泥的「雪走」被粗灰布条裹得严严实实，瞧着与寻常柴刀无异。行至十字街口，前头忽然闹哄哄地围了一圈人——几名穿着半截东瀛浪人羽织、头发胡乱束成顶髻的泼皮，正踹翻了一处卖艺老叟的铜锣架子。这帮人操着地道的海州土话，刀佩得歪歪斜斜，显是交了几两银子在藤原道场学了两手三脚猫的拔刀把式，便披上东瀛衣裳当街作威作福。老叟被刀鞘砸得额角见血，四周百姓指指点点却无人敢拦。你咬下最后一颗山楂，随手将竹签抛进路旁箩筐，右手拇指缓缓挑开了缠在刀柄上的灰布条。"},"宫中假凰":{"g":"男","level":"五境八关_一关开","faction":"蓟州 - 天人宫","loc":"蓟州·天人宫","job":"天人宫内门弟子","bg":"你是个不知来处的孤儿，天生一副雌雄莫辨的清丽皮囊。幼年流落蓟州雪地时，被外出办差的天人宫长老江惜星捡回山门。天人宫乃绝情绝义的隐世女宗，历代严禁男子踏入半步；偏偏江惜星在宫规森严的冷墙里压抑了半生，见你眉眼酷似女子、哭声微弱，心头竟鬼使神差地生出一丝逆反，将你作女童打扮带回宫中收为亲传。十余年来，全宫上下皆当你是个文静寡言的小师妹，唯有江惜星与你知晓这桩掉脑袋的欺瞒。白日里她是冷若冰霜的授业恩师，到了深夜无人处，她却常拉着你坐在烛下，将那些不敢对宫主江奉月吐露半字的孤寂与迷惘尽数倾倒给你。你是她在这座断情牢笼里唯一的寄托，你也甘愿敛去男儿气概，替养母守住这方摇摇欲坠的秘密。","money":"白银十五两","gear":"二品女装佩剑、天人宫弟子令","skillType":"preset","skill":"二品内功《寒月诀》、一品剑法《广寒剑诀》、二品轻功《踏月步》","scene":"开春以来，蓟州临海城里传出一桩怪事——众志盟梨园班新排了一出叫《唯一字情》的戏，许多定力深厚的武人进园子听了一遭，出来时竟个个神魂颠倒、道心大乱。宫主江奉月下令彻查，素来深居简出的江惜星却破天荒地主动接下了这趟差事。临行前夜，刚助你破入五境八关第一关的养母将你唤进内室。烛火下，她替你理了理女装衣领，手指罕见地有些发颤：「明日一早我便下山去临海城。宫中姐妹若问起，你只推说我是去追查当年叛宫执剑使的下落……但娘不同你撒谎，那出戏，我想去亲耳听一听。」在这座连笑声都算犯戒的冰冷深宫里熬了半辈子，你头一回在她眼底瞧见这般压不住的波澜。第二日天未亮她便披衣下山，偌大的偏殿里只剩你一人守着秘密，窗外寒月照着积雪，安静得让人心慌。","lockGender":true},"少谷主":{"g":"男","level":"五境八关_一关开","faction":"蜀州 - 死人谷","loc":"蜀州·死人谷","job":"死人谷少谷主","bg":"你幼年时的记忆是一片空白，只知自记事起，身边便只有义母朱颜改。十年前，这位名震天下的七境抱丹神魔【阎王】在蜀州绝谷立下规矩，收容天下走投无路的恶人，创立死人谷；而你便是这座恶人谷里唯一的「少谷主」。朱颜改用一枚死心神丹攥住了全谷恶人的性命，唯独待你千依百顺，将你视作这漫长枯燥岁月里唯一的乐子。她手把手教你《汉宫秋》与《桃花扇》，夜里常拉着你在灯下品评民间买来的俗套话本，笑谈外头的江湖风云。谷中那些昔日杀人如麻的巨寇见了你无不躬身退避，而你也对这位给了你姓名、武功与容身之所的义母满怀赤诚与濡慕。","money":"白银十两","gear":"二品短刀、死人谷令牌","skillType":"preset","skill":"自得奇功·后天内功《汉宫秋》、自得奇功·后天掌法《桃花扇》、自得奇功·后天轻功《梧桐雨》","scene":"今日义母朱颜改有事出谷，你在她寝居的书房里百无聊赖地翻找新话本，不慎碰落了博古架底层的一只旧木匣。匣内没有话本，只掉出一册纸页泛黄的陈年密账。你随手翻开，发现里头整整齐齐记录着十余年前的一批暗杀与灭门名录——翻至第三页时，你的目光骤然凝住。那上面不仅赫然写着你如今的名字，更列着十几个与你同姓的男女老幼，罪名一栏空置，而末尾「执行人」的朱批下，端端正正印着朱颜改昔日的代号。你对纸上那个被满门抹去的家族毫无印象，脑海里唯一的家便是死人谷；可指尖触着冰凉的泛黄纸页，那个每晚笑着替你掖好被角、听你念话本的义母面容，却与这页血淋淋的死簿重叠在了一处。院外忽然传来打更人孙不二的梆子声，你猛地合上账册，听见自己的心跳声在空寂的房中震耳欲聋。"},"太华遗孤":{"g":"男","level":"五境八关_四关伤","faction":"禹州 - 五岳剑派","loc":"禹州·太华山","job":"五岳剑派太华脉内门弟子","bg":"你出身禹州小有名气的镖局之家，自幼被送上太华山，拜在五岳剑派当代剑主、太华脉主岳左新门下，与大师兄令狐行、小师妹岳明珠一块儿练剑长大，情同手足。半年前你请假下山探亲，推开镖局大门，入目竟是满院横陈的尸首，自年迈祖母至襁褓幼弟无一活口。你忍着锥心之痛收敛亲人遗骨时，在父亲冰冷的腹腔中摸出一枚生吞入腹的蜡丸，剥开竟是一卷书于羊皮上的后天剑谱《葵水神剑》。此功阴柔诡谲、快似鬼魅，威力直追先天真功，唯扉页赫然注明「欲练此功，须先自宫」。你立时明白自家是因怀璧其罪才招来灭门横祸。六扇门与武林盟勘验无果，其余各脉脉主亦曾登门慰问；可那几道看似关切的目光落在你身上时，总叫你背脊发凉，隐隐觉得有人盯着的并非凶手，而是镖局失落的东西。你既未敢自残习武，也不敢向任何人吐露半字，只将羊皮剑谱密缝在贴身里衣夹层，半年来疯魔般苦修，终在日前一举冲破五境八关第四关「伤门」。","money":"白银二十两","gear":"一品宝剑「寒潭」、特殊物品《葵水神剑》剑谱（羊皮纸，缝于衣衫夹层隐秘珍藏，扉页注「欲练此功须先自宫」，阴柔极速、杀伤力堪比先天，疑为全家灭门之因）","skillType":"preset","skill":"后天内功《霞云经》、一品剑法《太华快剑》、一品剑法《朱陵巧剑》","scene":"晨钟撞破太华山的浓雾，你从满地血水的噩梦中猛然惊醒，第一件事便是按向胸口里衣——夹层里那张羊皮纸依然贴肉紧藏，冷汗却已湿透了后背。廊外传来熟悉的脚步声，大师兄令狐行拎着酒葫芦晃过窗前，见你推窗透气、神色惨白，随手将酒葫芦抛进你怀里：「又魇着了？灌两口暖暖身子。」你接过酒壶未曾言语，令狐行也收了平日的嬉笑，倚着栏杆正色道：「师父让我来通知你，五脉大会定在下月了。这回各脉年轻弟子都要下场比剑排定座次，你刚破入伤门关，师父点名要你代表太华脉出战。」话音未落，小师妹岳明珠已从隔壁院子探出脑袋，脸上既有替你担心的关切，又掩不住少女的雀跃：「师兄，爹爹说这次大会要商议五岳真正归一的大事呢！」你握紧案头的佩剑「寒潭」，望向云海彼端其余四座大山的险峻轮廓——五脉齐聚之日，那个灭你满门、觊觎剑谱的幕后黑手，定然也会坐在观礼席上。"},"元夕舞剑":{"g":"女","level":"五境八关_四关伤","faction":"楚州 - 元夕舫","loc":"楚州·元夕舫泊地","job":"元夕舫舞使弟子","bg":"你生于楚州水乡寻常百姓家，五岁那年因身段灵秀、眉目清婉，被元夕舫教习执事柳眉卿相中带回云梦泽。舫主公孙青见你根骨颇佳、性子外柔内刚，便收入内门亲授剑器与音律，更在近期破例传下镇派后天剑法《虞美人》与一品内功《水调歌头》。在连环画舫间，你与同门师妹竺寻芳、薛闻莺情同手足，常在月夜的甲板上赤足踏歌、对剑至天明；舫外往来中，你亦在商路盛典上结识了豪爽仗义的鹳雀楼千金贺少霜，又在随师长赴千锻峰修剑时，与铸剑山庄那位成日满手炭灰却笑颜明朗的欧阳巧成了挚友。元夕舫虽以歌舞词牌名动江湖，门中弟子却皆知祖训「盛世济民，乱世辅龙」。如今你刚破入五境八关第四关「伤门」，一柄青锋剑已初具倾城之势。","money":"白银三十两","gear":"二品青锋剑「踏月」","skillType":"preset","skill":"后天剑法《虞美人》、一品腿法《临江仙》、一品内功《水调歌头》","scene":"云梦泽晨雾浩渺，你赤足立于画舫船头，迎着江风演练完一趟《临江仙》。新破伤门关后，体内真气愈发充盈，连带舫主新传的那式《虞美人》也隐隐透出几分剑光美影交融的韵味。收剑入鞘时，小师妹薛闻莺怀抱乐谱自舱中快步走出，轻声唤道：「师姐，柳执事召咱们姐妹三个去主舱议事。」待你们步入舱房，柳眉卿正捻着一封洒金请帖凝神细看。见三人行礼，她将请帖置于案上：「鹳雀楼楼主贺潮生广发英雄帖，下月在沧江畔举办观潮大会，沿江备下酒席数千桌。明面上是邀天下同道共赏沧江大潮，实则是贺楼主想借势聚拢江湖人心。」一旁的竺寻芳闻言双眼微亮，柳眉卿却瞥了她一眼，转而将目光落在你身上：「舫主已应下此帖，命我带你们三人随行献艺。只是贺潮生此人豪气干云却又城府极深，排场铺得越大，水底下的暗流便越急。你刚破伤门，又得舫主厚赐，此去江夏城不仅要在天下群豪面前舞出我元夕舫的剑风，更要替舫中多看、多听。」","lockGender":true,"profs":"皮毛、、"},"关外狼子":{"g":"男","age":"18","level":"五境八关_三关生","faction":"燕州 - 关外盟","loc":"燕州·燕平城","job":"关外盟统领","bg":"你今年十八岁，是关外盟金家家主金古生抚养长大的义子。你自幼胸口便有一道天生般的青狼刺身，贴身戴着半块残缺古玉；金古生待你宽厚如亲生骨肉，连金家不传外姓的先天真功《灵木妙植》与《四时风雅颂》都倾囊相授，唯独对你的亲生父母讳莫如深，只说是故人之子。你在燕平城与马长缨、关长渊及金家义妹金南星一块儿长大，金南星自幼双目失明，十余年来都是你牵着她的手认路辨药，两人早已生出越过寻常兄妹的默契与温情。你为人敦厚笃实，一上疆场却悍勇如狼，年纪轻轻便修至五境八关第三关，凭着在镇北防墙外数次击退蛮族游骑的军功擢升统领，在盟中少壮派里威望仅次于马、关二位少主。","money":"白银三十两","gear":"二品长剑「戍狼」、半块古玉吊坠","skillType":"preset","skill":"一品内功《冰心诀》、后天拳法《四时风雅颂》、先天真功《灵木妙植》","scene":"塞外冬荒将至，你率队自镇北防墙巡防归来，顺道入燕平城书院交割军需文书。穿过书声琅琅的回廊时，迎面走来两名女子——居首那少女乌发如瀑，眉眼轮廓竟与你有五六分相似；她颈间悬着的半枚玉坠，更与你怀中那块严丝合缝。你心头剧震，下意识摸出怀中古玉，那少女目光扫过你手中的玉坠与微敞领口露出的青狼刺身，脸色霎时煞白，失声脱口：「你……你是……」她身侧那名唤作塔娜的精悍女护卫反应极快，一把攥住少女手腕，用草原胡语急促低喝了一句，随即横身挡在你面前，按刀冷冷逼视着你，护着那频频回首的少女翻身上马、绝尘而去。你攥着发烫的半块古玉一路奔回金府，叩开了养父金古生的房门。听罢方才的遭遇，金古生默然良久，终是长叹一声道出实情：十八年前，金月蛮王莽古勒曾化名潜入大凉，与一名汉家女子相恋生下一双龙凤胎；后行踪败露遭燕州群侠围剿，那女子死于乱军之中，莽古勒只抢出幼女突围北逃，被抛在荒草间的男婴则被金古生暗中抱回抚养至今。你立在廊下，听着窗外刮骨的燕州朔风——防墙外的蛮王是你血脉相连的生父，方才那少女是你的亲生胞妹，而脚下这片你要用命去守的关山，正是金月铁骑今冬叩关的目标。","lockGender":true},"蛊女寻踪":{"g":"男","level":"五境八关_二关休","faction":"黔州 - 五毒教","loc":"黔州·北路茶棚","job":"五毒教内门弟子","bg":"你出身黔州苗寨，幼年体弱将夭，被五毒教长老收入教中以百草毒虫续命，自此与蛊道结下不解之缘。圣姑蓝歆见你体质特异、能耐剧毒，便将你收为内门亲传，悉心传授毒功与后天蛊术《万蛊噬天诀》。你在教中与当代圣女蓝鸯自幼一块儿饲蛊练功，名为上下，实同姐弟。谁料数月之前，素来守规矩的蓝鸯竟留下一纸空笺，孤身一人悄然离教，自此杳无音信。圣姑蓝歆震怒之下，没有动用刑堂长老，而是密令刚破入五境八关第二关的你独自下山寻人，临行前只神色凝重地叮嘱了一句：「圣女体内的本命蛊王关乎十万大山深处的古封印，且离了总坛压制，不出半年便会蛊性反噬——赶在旁人发觉前，把她活着带回来。」","money":"白银十五两","gear":"二品蛊针「引梦」、蛊虫囊、一品蟾蜍宠物「呱呱」（等阶一品、等级听命、好感度35、能力：剧毒喷雾、蛊毒共鸣、夜视示警）","skillType":"preset","skill":"后天蛊术《万蛊噬天诀》、一品掌法《千蛛万毒手》、二品腿法《百足腿法》","scene":"你携着本命毒蟾「呱呱」出了苗疆，沿玉山城往北的官道一路暗中查访。这日午后行至一处山坳茶棚歇脚，还没等茶博士添水，一个浑身泥印的小丫头便自顾自地蹿到了你桌旁。她瞧着不过十六七岁，皮肤呈健康的蜜色，一双黑白分明的大眼睛亮得惊人，腰间斜插一根白森森的兽骨笛。不等你开口，她便端起你面前的粗瓷茶碗咕咚灌了一大口，抹着嘴咧嘴笑道：「我就说闻着一股顶香的蛊味儿，喂，你是五毒教出来的人吧？」你眼神微凛，指尖悄然扣住袖中「引梦」蛊针；她却浑不在意地晃着双腿，从怀里摸出半块干硬的杂粮饼晃了晃：「别紧张嘛，我叫巴月，刚从十万大山里偷跑出来的。你在找那个穿白衣裳、走路没声儿、身上带股冷花香的漂亮姐姐对不对？半月前我在山外林子里撞见过她，正急匆匆往北边赶呢！」你心头微震，没料到这野丫头竟一口道破了蓝鸯的行踪。巴月眼巴巴地盯着你桌上的花生米，眨巴着眼讨价还价：「外头好玩的东西多，可我身上没铜板啦——你管我一路饱饭，我给你带路找人，成不成？」","lockGender":true},"武备锦衣":{"g":"男","level":"五境八关_一关开","faction":"宸州 - 武备司","loc":"宸州·天凉城","job":"武备司锦衣","bg":"你出身宸州寒门，凭着一股狠劲考入武备司，从底层缇骑做起。武备司奉太祖「以武为备」的祖训监管天下武人，军纪严苛，行事讲究结阵碾压，平日与讲律法的六扇门、替皇帝干脏活的虎豹房极不对付。你在刀口上滚了三年，几番死战下来终于破入五境八关第一关，升任正五品锦衣，按例领到了一卷先天真功《星命照我》的残页抄本。只是这门真功须练至粗通、引动星辰入体后才能获赐星宿代号，你眼下才刚摸到门槛。平日里你在都督高徒赵曦文手下听调，同司中那位性子冷硬的七杀星君敖不平也打过几回交道。","money":"白银八十两（武备司俸禄）","gear":"二品雁翎刀、武备司锦衣腰牌（背面铸星纹）、一卷《星命照我》残页抄本","skillType":"preset","skill":"先天真功《星命照我》、后天内功《百战不悔诀》、一品刀法《威武霸刀》","scene":"天刚蒙蒙亮，户部仓场便出了命案。你带着一队缇骑赶到现场时，一名户部主事已被钉死在朱漆大门上，尸体尚未凉透。古怪的是，穿透他胸膛的是武备司制式雁翎刀，刀柄上却缠着六扇门捕快惯用的旧丝绦，摆明了是有人栽赃嫁祸。你还未来得及命人拔刀验尸，东巷已传来急促的脚步声，六扇门一名青绥捕头率众赶到；紧接着西侧院墙黑影一晃，两名虎豹房百户也翻墙落入场中。三家平日里本就势同水火，如今撞在同一桩命案跟前，气氛顿时剑拔弩张。六扇门青绥按着刀柄，一口咬定京城命案归刑部勘验；虎豹房百户则阴阳怪气地亮出腰牌，声称死者前日刚往内廷递过密折，尸首与卷宗必须由虎豹房带走。你挥手止住身后骚动的缇骑，上前一步按刀挡在仓门前——户部仓场关乎军械钱粮调度，在这块地界上，武备司绝无退让的道理。","profs":"皮毛、、"},"纯阳卫道":{"g":"男","level":"五境八关_一关开","faction":"凉州 - 纯阳宗","loc":"凉州·纯阳顶","job":"纯阳宗内门弟子","bg":"你自幼被凉州纯阳宗收养，在祈雪山脉的寒风雷霆里练剑长大。纯阳宗镇守大凉西陲，常年与大漠里的大梦教残部及西域邪派厮杀，门风刚烈，见着魔道妖人向来是拔剑就砍、绝无二话，江湖上不少圆滑之辈背地里都叫你们「死心眼的牛鼻子」。你拜在戒律长老雷不妄门下，老长老脾气硬得像山里的石头，把一门后天剑法《正心剑》传给了你。前几日你破入五境八关第一关，正式升入内门，平日里常跟着人榜第八的大师兄【惊雷剑】燕流云，还有那个爱逞强斗嘴的小师妹风絮一道下山巡边。","money":"白银二十两","gear":"二品雷纹剑、纯阳宗内门弟子令牌、三张驱邪黄符","skillType":"preset","skill":"后天剑法《正心剑》、一品内功《天雷正法》、一品剑法《狂雷震九霄》","scene":"西域大雪山的当代活佛旦增昨日派人送来请帖，邀中原各派下月赴西域参加二十年一度的「无上法会」。大雪山里头分作两支：活佛旦增统领的极善派慈悲苦行，与中原倒还相安无事；可另一支极恶派却专拿活人血骨炼制法器，纯阳宗上下对其早已恨之入骨。今晨大殿议事，戒律长老雷不妄拍案喝道「既然请了，就去把那帮妖僧盯死」，掌教青天子便当即定下由大师兄燕流云带队，点名让你与风絮随行护法。散会后走出大殿，山风吹得道袍猎猎作响，风絮迫不及待地凑过来拍了拍剑鞘：「师兄，这回大菩提寺和武林盟的人也去西域，要是大雪山极恶派的那群恶僧敢在法会上露头，咱们砍是不砍？」燕流云脚步未停，只淡淡瞥了你二人一眼：「进了西域先听我号令行事，真撞上拿活人炼器的妖孽，不必留手。回去收拾行囊，后日一早启程。」"},"陇西将种":{"g":"男","level":"五境八关_一关开","faction":"晋州 - 陇西李家","loc":"晋州·赈粮村落","job":"陇西李家左营统领","bg":"你是晋州陇西李家的旁支子弟。李家手握三万私兵驻守雍山城外，明面上是朝廷册封的世袭侯门，实则把晋州经营得针插不进，是个听调不听宣的土皇帝。堡里规矩极严，以军法治家，哪怕是侯爷亲儿子犯了军规也要当众挨军棍；可嫡庶尊卑的门槛也高得吓人，外姓高手哪怕修到气海境也只能当个家将。你虽姓李，到底是个旁支，自幼在军营里和普通兵卒吃一锅饭、滚一身泥，跟教习坊总教头尉迟敬练出了一手狠辣扎实的沙场枪法。这几年你在年轻一辈里罕有敌手，唯独跟族里那位天赋妖孽的四公子李驷元切磋了三场，三场皆输得心服口服。前几日你破入五境八关第一关，在校场大比中夺下魁首，被少家主李壹城提拔为左营统领，成了左营李壹城与右营二小姐李贰凰争权之间的一员实权干将。","money":"白银五十两（月例）","gear":"二品铁枪、李家左营统领腰牌、二品北地战马「乌骓」（虽烈但极识主，闻号即至，夜行不迷）","skillType":"preset","skill":"后天枪法《擂鼓瓮金枪》、后天横练《黄河两岸神功》、一品轻功《八骏行》","scene":"晋州自打去年开春就没落过一场透雨，大旱之后紧跟着蝗灾与时疫，到了秋里更闹了一场大地动，雍山城外震塌了半座黄土塬，不知多少百姓死在塌陷的窑洞里。熬到今年正月初五，塬上已是十室九空。莲花帮的弟子在沿途搭棚施粥，偃师坊连夜赶造提水机括，而手笔最大的还属陇西李家。今日你率左营骑兵，押送三十大车粟米进村放粮。路边的老榆树早被饥民剥光了树皮，墙根下缩着的灾民瘦得只剩一把骨头，见了粮车连哭喊的力气都没有。可车队刚在晒谷场停稳，随行的账房先生便先一步跳下马车，按着名册逐户核对画押，同时几名老兵熟练地掀开粮车底板，取出一捆捆丈量田亩的绳尺与木桩。一名老卒凑到你马前低声解释：「统领，侯爷早有交代，秋里地动把地界全震乱了，趁着开仓放粮，顺手把那些绝户无主的荒田丈量立桩，收归军屯。」你握着铁枪抬眼望去，远处黄尘漫天，二小姐李贰凰麾下的右营骑兵已经打着旗号在塬下跑马圈地；而在不远处的土坡上，晋州乔家票号的几辆黑篷马车正静静停着，冷眼旁观着李家的一举一动。"},"沧江护商":{"g":"男","level":"五境八关_一关开","faction":"楚州 - 鹳雀楼","loc":"楚州·江夏城","job":"鹳雀楼护商教头","bg":"你是楚州鹳雀楼的护商教头。鹳雀楼由楚州十几家大商帮凑份子立起，把持着内陆大半的水陆码头与江河漕运。楼主【大潮剑王】贺潮生在江湖上素有「及时雨」的名号，沿江常设义庄粥棚，虽与海州楼家抢生意抢得头破血流，吃相却比楼家好看得多。你是江夏城码头扛活的苦力出身，从小在水里泡大，凭着不要命的狠劲一路打进五境八关第一关，被漕运总甲提拔成了护商教头。这差事听着威风，实则两头受气——楼里的大掌柜只管催船期、算损耗，半点不管水路上的凶险；反倒是贺楼主花重金从泰西请来的大客卿【仁王】威廉·亚当斯脾气爽快，见你肯下苦功，闲暇时指点了你几手泰西的圣光斗气与重剑路数。","money":"白银一百二十两（这趟镖的定钱）","gear":"二品分水刀、鹳雀楼护商教头令牌、一卷楚州漕运水图（残）","skillType":"preset","skill":"后天内功《圣光斗气》、一品掌法《覆舟重掌》、二品剑法《十字绞杀剑》","scene":"沧江春潮将至，楼主贺潮生广发英雄帖，定于半月后在江夏城外举办「观潮大会」，沿江摆开数千桌流水席，打算借着天下群豪捧场的声势，狠狠压一压死对头海州楼家的气焰。眼下离正日子还有半个月，江夏城里已是鱼龙混杂、客栈爆满，你带着二十名校刀手在码头日夜轮值，连合眼都不敢踏实。偏偏这两日城里邪门事不断：前夜你在西街赌档后巷撞见两个穿孝服的怪人，塞银子给伙计打听城郊哪儿有刚埋的青壮新坟，你派人跟上去，不到两条街便跟丢了踪影；到了今早交班，巡夜的弟兄又来禀报，说临江几家客栈里，有好几个外地来的江湖客在睡梦中被人贴着头皮剪走了一绺头发，直到早上起床才发觉。你觉出里头透着邪气，急忙去向漕运总甲禀报，总甲听罢却只是皱眉敲了敲桌子：「观潮大会在即，贺楼主最忌讳这时候闹出乱子。你带人暗中盯着便是，没有实据之前，万不可打草惊蛇、惊扰了赴会的贵客。」"},"云海猎手":{"g":"男","level":"五境八关_一关开","faction":"琼州 - 海山族","loc":"琼州·珍珠湾","job":"海山族雾岭寨猎手","bg":"你是琼州五指峰雾岭寨的海山族猎手。三十年前大凉水师炮轰琼花岛，当年的岛国王室开城投降，摇身一变成了如今享福的琼花侯府；唯有世代住在深山里的海山族死不低头，退入中部云雾缭绕的高山雨林，成了整座岛上唯一还在跟朝廷对抗的部族。三十年来，水军都护府进山围剿了七回，琼花侯府替官军带路三回，双方死伤无数，却谁也没能摸进雾岭寨的大门。海山族人从不用刀剑，一身武艺全是从山林狩猎与泥地摔跤里磨出来的贴身锁拿功夫。你从小跟着首领瓦丹练摔跤，同巫祝的女儿伊婉进山采药，与飞毛腿达古斯、大力士拉达努一块儿长大。三年前你在山外盐场撞见侯府恶奴活活打死族人，赤手空拳冲上去扭断了那护院的脖子，前几日更顺势破入五境八关第一关，成了寨子里年轻一辈的顶梁柱。","money":"白银三两（山外换来的散碎银子）","gear":"藤木短棍（打猎用，非族中兵器传承）、雾岭寨烟号竹管、一篓解毒草药","skillType":"preset","skill":"后天轻功《雾岭遁》、后天擒拿《天地返》、一品内功《五指峰心法》","scene":"正月初五，你随首领瓦丹换上汉人百姓的粗布衣裳，下山去珍珠湾换购食盐。珍珠湾的珠池每年秋天开海采珠，捞上来的珍珠要被水军都护府、琼花侯府和海州楼家刮走三层油水，剩下的残羹冷炙才归拿命潜水的珠户。如今才刚开春，海滩上却已摆开了官案，水军官差、侯府家丁与楼家账房逼着全湾珠户聚在滩头，强令他们在今年再加三成抽分的新契上按手印。几十名皮肤黝黑的珠户围在案前苦苦哀求，说状纸半月前就递进了府衙，再加三成全家就只能跳海了；官差却一脚踹翻了领头的老珠户，骂骂咧咧地举起了水火棍。不远处的礁石边，几个还不懂事的珠户孩童正怯生生地望着这边，而高坡上渔父教的旧祭台、朝廷修的海神庙与南洋蕃僧的精舍遥遥相对。瓦丹冷着脸按住你绷紧的肩膀，低声道：「走吧，盐已经到手了，别在滩头上惹眼。」他转身往入山的林道走去，见你仍盯着海滩上的官差，脚步顿了顿：「想管闲事，也得先把那几个领头狗腿子的脸记熟了。白日里官兵势大，你要是现在冲出去送死，老子可不会替你收尸。」"},"礼署青衫":{"g":"男","level":"三境明气","faction":"无门无派","loc":"宸州·天凉城","job":"礼部主客司主事","bg":"你生在宸州天凉城一户底层书吏家里，打小就在老爹当差的衙门值房里帮着抄写公文，日子久了，把一部《大凉律》和科考经义背得滚瓜烂熟。二十岁那年你挂着锦州文华书院外舍生的名头下场乡试中举，第二年春闱又撞大运考中了三甲同进士——名次虽然垫底，总归是正儿八经的进士出身。散馆后你被分到礼部主客司，当了个从七品主事，专门负责外邦藩属进京朝贡时的礼仪接待。这差事事情杂、油水少，部里那些有背景的同年都不爱干，唯独你耐得住性子，把东瀛、高丽和西域各国的迎送规矩打理得井井有条。早年在文华书院读书时，你曾得院长许墨然指点，靠着水磨工夫把一门《自华决》练到了登堂，剑术在文官进士里也算拔尖；只是三境明气的修为放在藏龙卧虎的天凉城里，实在不够看。","money":"白银三十两","gear":"三品文剑、礼部告身文书、旧书一箱","skillType":"preset","skill":"自得奇功·三品剑法《临川剑法》、自得奇功·二品内功《自华决》、自得奇功·二品剑法《王将军剑诀》","scene":"正月初五，礼部主客司便接了一桩烫手山芋：西域三十国之首的哈番国使团已经过了凉州，月底前就要抵达天凉城朝贡。哈番国主【通天神拳】哈勒泰是天榜有名的抱丹神魔，使团里头跟着不少西域武道高手，按朝廷规矩，这类外邦武人进京必须由兵部和武备司协同礼部布防。可主客司发往兵部与武备司的公文递上去好几天了，两边都在踢皮球，连个准信儿都没有。司里的郎中大人嫌武备司那帮武夫难打交道，干脆一推六二五，把这跑腿催文的苦差事塞给了你；临出门前，老上司还把你拉到廊下低声交代，让你借着接待使团的机会，替礼部尚书卢守礼大人暗中摸一摸西域使团这回进京的真实底细。你夹着两卷厚厚的公文迈出礼部衙门，千步廊外朔风扑面，天凉城开春的第一场雪正纷纷扬扬地落下来。","profs":"、登堂、","lockGender":true},"魂穿龙裔":{"g":"男","n":"敖","level":"五境八关_一关开","faction":"无门无派","loc":"宸州·天凉城","job":"大凉皇室旁支子弟","bg":"你是七天前在这具身体里醒过来的。前世在地球二十多年的记忆清清楚楚，反倒是这具身体原主留下的记忆碎得七零八落——你只知道自己如今是大凉皇室敖家的偏支子弟，六岁起按族规练《皇家锻体决》，十二岁那年被宗人府的族老挑中，送进秘库当了试药的活靶子，强行灌药修习那门只有皇室核心嫡系才能碰的先天真功《天蛟换骨》。九死一生的剥皮换骨熬过来，修为固然被生生拔到了五境八关第一关，一身经脉却也落下了不少暗伤。去年秋猎，原主在皇家围场里莫名其妙地坠马重伤，在床上躺了三个月没能熬过去，一命呜呼后才换成了你。原主咽气前脑子里最后一道念头，便是死活想不通秋猎那天，到底是谁暗中动了手脚，引他挑中了那匹发狂的烈马。","money":"白银三百两（偏支月例）","gear":"一品佩剑「听涛」、敖家偏支玉牌、秋猎那副断了的马鞍","skillType":"preset","skill":"自得奇功·先天真功《天蛟换骨》、自得奇功·后天内功《真龙皇极功》、自得奇功·后天拳法《镇国九鼎拳》","scene":"你醒来刚满七天，伤还没利索，宗人府的传召便到了跟前。阴暗肃穆的宗正府偏厅里，八十五岁的老宗正敖江还坐在上首太师椅上——这位太祖皇帝的第七子、如今皇室仅存的抱丹神魔，只抬眼扫了你一下，你体内《天蛟换骨》的气血便不受控制地一阵翻腾。老宗正慢条斯理地端起茶盏吹了吹浮沫，随口问道：「身子骨还算硬朗。去岁秋猎在围场里摔断了马鞍，躺了三个月，还记不记得那天是谁递给你那根马缰绳的？」你心头一凛，原主坠马前的记忆本就是一团浆糊，只能恭恭敬敬地低头回禀说摔坏了脑子、实在记不真切。敖江还不置可否地哼了一声，从案头拈起一份刚送来的急报丢到你脚边。那是今日一早户部仓场的命案奏报：一名户部主事被人用缠着六扇门丝绦的武备司雁翎刀钉死在仓门上，如今六扇门、武备司和虎豹房三家正围着尸首打嘴仗。「这死鬼主事三天前刚往宫里递过一份密折，折子里参了宗室三个人，第一个名字就姓敖。」老宗正放下茶盏，苍老的声音在空旷的大厅里回荡，「你前脚在秋猎坠马，他后脚就死在仓门前，两件事栓在同一根绳上。不出三天，那三家的人都会上门找你问话。滚回去把嘴擦干净，想清楚待会儿怎么应付他们吧。」","lockGender":true},"黄粱一梦":{"g":"男","level":"三境明气","faction":"无门无派","loc":"凉州·边城旧宅","job":"凉州边陲小世家弟子","bg":"你本是凉州边陲小世家里的旁支子弟，天资平庸，自幼在族人的冷眼与轻慢中苟活；直到那年大漠风沙漫卷，你阴差阳错沦入大梦教残部。在魔教的刀山火海里，你如履薄冰地隐忍了数十年，于诸王掣肘与代教主的猜忌间合纵连横、步步染血，终在一朝暴起反噬，斩铜头象王赫连博山于铜座之下，更凭惊世执念强行补全《大梦神功》残篇、逆天抱丹，魔威震慑西陲。那数十载峥嵘岁月里，你屠纯阳青天子、斩紫气龙王慕容铎、裂哈番国主哈勒泰，将荆南柯、风絮、哈雅尽数收作阶下之囚，一人身兼《大梦神功》《九霄雷诀》《虎凰炎坼》三门先天真功，横霸凉州。然而就在你整饬大军、欲彻底重现大梦教吞天霸业之日，武林盟主【剑神】秦白、虎豹房【老督主】曹写仁与一尊神秘莫测的猫妖竟联袂压境。绝巅强者联手之下，你连对方招式路数都未及看清，数十年苦心经营的基业便已化作齑粉；最终一记不知自何处破空而来的无声神箭洞穿了你的心口。弥留之际，你穷尽《大梦神功》化虚为实的极境，拼尽毕生元神将一缕执念凝作古拙玉蝉逆流送出……再睁眼时，入目仍是凉州边城老宅阴湿漏风的柴房偏厢，经脉间只有堪堪三境明气的微末内息，唯掌心死死攥着那枚温凉玉蝉，叫你一时分不清那纵横西域的数十年究竟是前尘，还是一场黄粱大梦。","money":"","gear":"玉蝉","skillType":"preset","skill":"自得奇功·先天神通《定北游》、自得奇功·先天真功《大梦神功·残篇》、自得奇功·三品内功《小周天引气术》","profs":"圆满、皮毛、登堂","scene":"柴房破门外传来族兄肆无忌惮的嗤笑与踹门声，喝令你速去马厩铡草喂马。你盘膝坐在冰冷的破草席上，掌心那枚玉蝉微光流转，随着你下意识催动本命神通【定北游】，识海深处隐有隔世蝉鸣回响，一缕灰蒙蒙的梦意自玉蝉溢出，在膝前凝成几页墨迹未干的《大梦神功·残篇》行气总纲。「砰」的一声闷响，破旧木门被外头一脚踹开，夹杂着沙砾的凉州寒风呼啸灌入。你垂眸敛去眼底历经沧桑的寒芒，不动声色地将残页拢入袖中，体内运转的虽只是三境明气的《小周天引气术》，掌心玉蝉的余温却真实得可怕。"},"星海溯古":{"level":"无修为","faction":"无门无派","loc":"高丽·平壤","job":"高丽平壤的抄书人","bg":"六百年后的天穹终究化为焦土。在降临的外星侵略者面前，人类曾引以为傲的深空舰队与轨道巨构接连瓦解。由于数百年来文明只专注于科技跃迁，彻底废弃了肉身淬炼，终在毁灭性的战局中一溃千里。垂死的人类聚齐了所有残存储藏，甄选出体质适宜且潜藏白泽血脉的你。启程之前，人类强行唤醒了你的白泽血脉，又给你服下整整十五份“0号营养液”以加强体质。沉睡的古脉就此苏醒，本体神通《万物情理》也随之显现；你身无兵刃，终究只是个肉体坚韧却全无修为的凡躯。\n\n按绝密的救亡方略，你本该通过时空跃迁回到大灾降临前百年的旧世，唤醒祖辈重拾武道以求抗衡。然而时光设备剧震偏航，生生将你多回溯了整整五百年，更将你抛落在大凉时期的异邦高丽，而非故土中原。历经时空乱流冲击，身上原属先天的时空防护服破损后跌落至后天品质，如今只剩拟态功能；怀中那台个人终端已经没电，目前无法工作，唯有出发时带上的五块金砖仍完好地压在行囊底部。\n\n你对此世本无认知，只能隐姓埋名于高丽平壤的市井，靠帮人抄书维持生计，三个月里始终不敢拿出那些金砖，跟着市井武师学了粗浅桩功与地躺拳，尚只会些皮毛。在穿梭于鱼市与巷陌的日常里，你错愕地发现，这个时代人人皆知习武乃立世之本，草莽走卒亦重气力。若在此刻高呼警惕天外之敌、劝导万民练武，只会被当成失心胡言的疯汉。\n\n你记忆中的那场侵略发生在六百年后。海风吹动拟化的粗布衣角，你站在高丽的石滩晨雾里，摸了摸毫无反应的个人终端。劝人练武的任务已经无从谈起，可那些送你出发的人，仍将未来的希望托付给了你。","money":"白银一两；已经没电的个人终端×1，金砖×5（出发时随身带上）","gear":"兵刃：无；防具：破损的时空防护服（后天，原为先天，当前仅剩拟态功能）；天材地宝：0号营养液（后天）×15，全部已服用","skillType":"custom","skill":"自得奇功·先天神通《万物情理》、自得奇功·不入流横练《粗浅桩功》、自得奇功·不入流拳法《地躺拳》","profs":"圆满、皮毛、皮毛","whyNoRealm":"来自六百年后只发展科技、不练武的时代，此前完全不了解大凉时代；白泽血脉与天材地宝强化了体质，仍未修出内力。","scene":"你在高丽平壤的市井间隐姓埋名，靠替书铺抄书糊口已满三个月，行囊底部的五块金砖始终未敢露白。这日清晨，你将依旧黑屏沉寂的个人终端贴身收好，抚平拟态成寻常粗布短褐的防护服准备出门。巷口武馆里照例传来学徒们晨练的呼喝声，而在几名过路武人与脚夫的闲谈中，你终于听到了苦等三个月的消息——开往大凉蓟州与海州的跨海商船已经入港，五日后便要起锚返航。"},"玄绥游侠":{"g":"男","age":"18","level":"五境八关_三关生","faction":"无门无派","loc":"宸州·天凉城","job":"江湖游侠（暗受玄绥令的金绥遗孤）","bg":"你的父亲曾是六扇门金绥捕头，早年因查办朝中贪墨大案而为国捐躯。如今更启帝敖澜登基半载，意欲整顿朝纲、制衡江湖，却苦于外朝六部党争掣肘、内廷虎豹房目标太大，遂在暗中相中了身家清白且已修至五境八关第三关的你。今日你奉密诏悄然入宫，年轻的天子于偏殿亲赐下一枚黑底金边的「玄绥令」，命你平日仍以无门无派的江湖游侠身份行走十三州。\n\n这枚玄绥令不设常驻品阶，亦无调兵搜查之权，唯独准你越过百官直达天听、入宫面圣。自此之后，圣上的密旨会经由六扇门的隐秘暗桩传至你手中，或令你暗中配合朝堂落子，或命你彻查地方大员与宗门的猫腻。你在江湖行走所需的功法秘籍与灵药珍宝，可在合理范围内向内廷武库支取，办妥差事更有厚赏；但每接下一桩差遣，你也须时刻权衡皇权与朝廷的利害，待返京述职时在御前如实交代。\n\n玄绥令须贴身密藏，一旦密使身份走漏，江湖各派必视你为朝廷鹰犬，而朝中各怀鬼胎的部堂大员亦会不惜代价将你除之后快。","money":"银钱：50两；随身物品：黑色金边玄绥令×1（只准直达天听、当面汇报，其他权力随任务另授）","gear":"兵刃：百炼雁翎刀 一品；防具：蚕丝软甲 一品","skillType":"custom","skill":"自得奇功·一品刀法《杏花微雨燕双飞》、自得奇功·二品内功《潜龙勿用诀》、自得奇功·一品擒拿《分经错骨手》","scene":"你刚刚在御前躬身领旨，敛息退步迈出偏殿门槛，身后沉重的朱漆铜钉殿门便在低沉的枢轴声中缓缓合拢。正月的冷冽日光倾洒在巍峨森严的天凉城皇宫内，重檐庑殿顶上的琉璃瓦折射出刺目的金芒，汉白玉御道两侧的披甲禁军如铁铸般肃立不语。那枚黑底金边的玄绥令正贴在胸口内袋，隔着蚕丝软甲犹带几分寒意，你的指腹无意识地摩挲过令牌边缘凸起的金线。一阵夹着碎雪的穿堂风掠过深邃宫墙，吹起你的游侠劲装衣角；丹墀拐角处，一名身穿素青袍服的引路内侍悄步上前，低眉垂首，无声地朝你做了一个请出宫门的手势。"},"月下双生":{"age":"18","level":"无修为","faction":"无门无派","loc":"罗刹国·北地庄院","job":"罗刹国地主庄院的农奴","bg":"你在罗刹国北地的凛冬寒风里冻得瑟瑟发抖。身上只有一件破损肮脏的粗布麻衣，没有姓名，没有铜钱，也未学过半点武艺。在这处地主的庄院里，自从被强征为农奴后，你便像牲口般受人役使，脑中始终浑浑噩噩，旁人打骂呼喝，你只知低头挨着，连挨打的缘由也想不明白。今夜寒气彻骨，你因饥寒难眠，蜷缩在麦秸堆旁偶然仰起头。月亮忽然变了颜色：疯狂的黄月，杀戮的红月，沉寂的黑月，最后是纯洁的银月。你揉了揉眼，那月色分明还是寻常的清冷残月。可你突然想起了从前的事，浑浑噩噩的十八年间受过的冻、挨过的饿、见过的风霜泥泞，一幕接着一幕，连之前听不懂的话也听懂了。你还不知道世人把这叫作开智。一个女声在脑海中响起，怜惜而略带魅惑，吟诗般地说：“你就是我，我就是你。我亲爱的，你在幕前顺着命运行走，命运在你的前方展开；我在幕后接触世界的真实。即使你在猜忌，我们也同为一体。我因你而存在，你因我而完整，我们没有区别。”","money":"银钱：无","gear":"兵刃：无；防具：破旧粗布衣（不入流）；其他灵物、宠物：无","skillType":"custom","skill":"自得奇功·先天神通《呢喃诗章》","profs":"圆满","scene":"寒风卷着碎雪掠过庄院荒芜的打谷场。你从麦秸堆旁慢慢直起身，清冷的月光落在脸上。你还没理清那些纷乱的记忆，她又温柔地开口：“现在是通用历法1452年1月5日。命运的道路已经在你面前展开，我亲爱的。月光照耀着你，星空之下，你已目见了自己曾经所做的一切。现在，你是甘于平凡，还是渴望不朽？世界如同海洋，你是否有勇气，去探寻平安的孤岛之外的一切？”庄院里仍是一片寂静，麦草上积着薄雪，屋里的庄户还未醒来。","whyNoRealm":"十八年来神智浑噩，被地主强征为农奴，只知听命劳作，从未学会锻骨、吐纳或习武；今夜才刚刚开智。"},"九尾封孤":{"g":"男","age":"16","level":"三境明气","faction":"木叶派","loc":"禹州·阳洛城","job":"木叶派掌门遗孤","bg":"你是禹州阳洛城木叶派前任掌门的独子。木叶派原本只是阳洛城中一家名不见经传的三流小派，直到你父亲横空出世——他天纵奇才，年纪轻轻便修至八关气海满盈，更在生死搏杀间领悟出极境真意，被禹州武林公认为最有望叩开七境抱丹的少年宗师，木叶派也因他一人而声威大振。然而十六年前的那个血夜，祸乱上古的一代妖王【九尾妖狐】突现阳洛城外，赤地百里。你父亲为护全城生灵与宗门基业，孤身提刃与九尾妖狐血战整整一夜，最终拼尽本命元神，将重创的九尾妖狐硬生生封印进刚降生的你腹中，自己则油尽灯枯、立毙当场。顶梁柱一朝崩塌，木叶派瞬息跌落神坛，打回昔日人人可欺的衰落小派原形。门中长老与弟子不敢怨恨早已灰飞烟灭的妖灾，便将满腔的不甘与恐惧全撒在了你头上——他们视你为克死掌门、拖垮宗门的不祥灾星，十六年来对你非打即骂、百般折辱，连基础的门派心法都不肯好好传授，你全凭自己偷看演武、熬打皮肉，才勉强踏入三境明气。直到今日，你在后山柴房顶着寒风揉搓淤青时，下腹丹田深处忽然响起了一道慵懒蚀骨、带着滚烫热气的女人轻笑声……","money":"铜钱八十文","gear":"磨损铁苦无（三品）、洗得发白的木叶旧练功服（不入流）、生锈护额","skillType":"custom","skill":"自得奇功·三品轻功《木叶瞬身步》、自得奇功·三品腿法《木叶旋风腿》、自得奇功·先天神通《灼幽烈阳》","profs":"粗通、粗通、圆满","scene":"冬日的寒风从木叶派后山柴房的破窗灌进来，你刚被外门执事借口「扫雪不净」克扣了半月口粮，还挨了两记闷棍。你缩在草堆上，正哈着白气往手臂淤青处涂抹劣质药油，下腹肚脐处那道伴随你十六年的漆黑八卦封印纹路，忽然毫无征兆地滚烫起来。紧接着，你眼前的景象一阵模糊，意识竟跌入了一片幽暗潮湿的地下水道。水道尽头矗立着两扇高达数丈的赤红铁栅栏，栅栏正中贴着一张古拙封符；而在铁栅后方的阴影里，九条蓬松如金色云霞的巨大狐尾正缓缓摇曳，将一具丰腴曼妙、曲线惊心动魄的赤足胴体半掩其中。那生着一对毛茸茸金狐耳、容颜妖媚入骨的金发尤物正慵懒地斜倚在自己暖融融的尾巴堆里，修长白皙的玉腿交叠晃荡，一双流淌着熔金光泽的狭长狐眸隔着铁栏上下打量着你，殷红唇角勾起一抹勾魂夺魄的弧度：「看了十六年笑话，也有点无聊了……喂，外头那个挨揍的小鬼，你就甘心顶着你那混蛋老爹的遗泽，被这群连给姐姐提鞋都不配的废物天天骑在头上作践？凑近点，跟姐姐聊聊……要不要借一点我的力气使使？」","lockGender":true},"吞指幼虎":{"g":"男","age":"16","level":"四境开窍","faction":"无门无派","loc":"禹州·阳洛城外废庙","job":"阳洛城游侠少年（绰号「阳洛幼虎」）","bg":"你本是禹州阳洛城里一名再寻常不过的市井少年，自幼与爷爷相依为命，为人最是讲义气、明事理。你平日里也没什么大志向，闲暇时喜欢在街头巷尾耍鸡斗犬、同街坊半大小子打抱不平；偏偏你天生一副异于常人的钢筋铁骨与怪力，寻常人苦熬数十年才得贯通的七窍，你年纪轻轻便水到渠成踏入四境开窍，使得一手刚猛利落的好拳掌，阳洛城南街北巷的混混与武馆学徒见了你都得服软，久而久之便给你起了个「阳洛幼虎」的绰号。前几日你与几名常在一起厮混的伙伴在城外古冢边避雨，同伴无意间从坍塌石砖下摸出一只贴满残破黄符的旧木匣，里头装着一根干枯发黑、指甲森长如紫铜的诡异手指。谁也没当回事，只当是哪个邪门歪道落下的陪葬死物；谁知今日傍晚，两名浑身血气的魔门妖人竟顺着气味追杀而至，出手便是索命的狠招。","money":"白银二两、铜钱三百文","gear":"缠手粗布带（不入流）、铁胆一对（三品）、半旧连帽短褐（三品）","skillType":"custom","skill":"自得奇功·二品拳法《烈虎下山》、自得奇功·二品内功《壮血吞气功》、自得奇功·三品横练《铜皮铁骨功》","profs":"登堂、登堂、圆满","scene":"城外荒废的山神庙里血腥气刺鼻，你的两名同伴已被魔门妖人震断肋骨、死死踩在碎砖地上，那名领头的黑衣魔修五指成爪，正欲捏碎同伴的喉骨夺走那根干枯手指。你双目赤红，一记《烈虎下山》轰开侧面刀手，虎口抢过那截冰冷刺骨的怪异腊指。身后两柄淬毒血刃已封死所有退路，眼看今日断无幸理，你想起方才魔修嘴里念叨的「吞下圣指便可获无上妖力」，救人心切之下把心一横，仰头便将那根干硬恶臭的怪指生生咽进了肚里！刹那间，一股仿佛积攒了千年的滔天凶煞自胃袋轰然炸开，你脸颊眼下骤然浮现出几道诡异的黑色咒纹，耳畔响起一个高傲、狂肆又透着几分慵懒的女声：「哈……一千年了，外头的空气还是这么让人反胃。不过小鬼，你这具皮囊倒还算结实。」黑衣魔修尚未反应过来，你右手竟不受控制地随手一挥，一道凌厉无匹的无形斩击瞬间将庙门连同两名魔修的护体兵刃劈得粉碎！你猛地咬破舌尖，凭着天生恐怖的肉身韧性硬生生压下体内那股喧宾夺主的意识。就在你扶着断柱大口喘息时，残破的庙墙上忽然传来一阵啪啪鼓掌声——一名白发如瀑、眼眸湛蓝如海的女人正翘着二郎腿坐在墙头，咧嘴露出一口森白尖利的鲨牙，饶有兴致地俯视着你脸侧尚未完全消退的黑纹：「哟，本想顺路接个武林盟的除魔外包换两坛酒钱，没想到你这小鬼倒有点意思？喂，现在说话的，是你自己，还是里头那位“前辈”？」","lockGender":true}};
