/* 正本武学品级由本卡目录确立；新增自定义武学继续使用原有境界限制。 */
function knownOpeningGrade369(name){
  const n=String(name||'').trim().replace(/^《|》$/g,'');
  if(OPENING_CANONICAL_GRADES369[n])return OPENING_CANONICAL_GRADES369[n];
  const preset=PRESETS[document.getElementById('preset')?.value||''];
  for(const part of String(preset?.skill||'').split('、'))if(part.includes('《'+n+'》'))return part.match(/(不入流|三品|二品|一品|后天|先天)/)?.[1]||'';
  return '';
}
function syncKnownOpeningGrade369(row){
  if(!row)return '';
  const sel=row.querySelector('.cs-grade'),name=row.querySelector('.cs-name')?.value||'',fixed=knownOpeningGrade369(name);
  if(!sel)return fixed;
  if(fixed){
    let option=Array.from(sel.options).find(o=>o.value===fixed);
    if(!option){option=document.createElement('option');option.value=fixed;option.textContent=fixed;sel.appendChild(option);}
    option.disabled=false;sel.value=fixed;sel.disabled=true;sel.dataset.canonicalGrade369=fixed;
    sel.title='已有武学的品级随正本固定';sel.setAttribute('aria-label','品级（正本固定）');
  }else if(sel.dataset.canonicalGrade369){
    const prev=sel.value,level=document.getElementById('level')?.value||'',allowed=openingCustomGrades396(level);
    delete sel.dataset.canonicalGrade369;sel.disabled=false;sel.title='';sel.removeAttribute('aria-label');sel.replaceChildren();
    for(const grade of allowed){const option=document.createElement('option');option.value=grade;option.textContent=grade;sel.appendChild(option);}
    sel.value=allowed.includes(prev)?prev:(allowed.includes('三品')?'三品':allowed[0]);
  }else sel.disabled=false;
  return fixed;
}

