  const level=document.getElementById('level')?.value||'',allowed=['不入流',...allowedGradesFor(level)],preset=openingPresetMatches347();
  if(preset&&fixed412.length&&document.querySelectorAll('#custom-skills .custom-skill-row').length!==fixed412.length)throw Error('预设武学数量固定，不能额外增加武学。');
  const accepted=(name,grade)=>{const fixed=knownOpeningGrade369(name);if(fixed&&fixed!==grade)throw Error('《'+name+'》的正本品级为'+fixed+'，不能另改品级。');return allowed.includes(grade)||Boolean(preset&&String(preset.skill||'').split('、').some(part=>part.includes('《'+name+'》')&&part.replace(/^自得奇功[··]?\s*/,'').startsWith(grade)));};
  if(document.getElementById('skill-type')?.value==='custom'){
    for(const row of document.querySelectorAll('#custom-skills .custom-skill-row')){const name=row.querySelector('.cs-name')?.value?.trim();if(!name)continue;const grade=row.querySelector('.cs-grade')?.value||'';if(!accepted(name,grade))throw Error('《'+name+'》的品级不符合当前境界，请重新选择。');}
