  }
}

function applyPreset() {
  document.getElementById("opening-plot").value = "";
  var key = document.getElementById('preset').value;
  if (!key) {clearOpeningPreset347();clearOpeningMartial347();const faction=document.getElementById("faction");if(faction)faction.value="无门无派";updateFactionInfo({restore347:true});return;}
  var p = PRESETS[key];
  if (!p) return;
  // 清空玩家自填项
  p.n = p.n || ''; p.age = p.age || ''; p.nick = ''; p.look = '';
  applyDataToForm(Object.assign({},p,{preset:key}));

  // 解析武学并正确填入界面
  var skillStr = p.skill || '';
  var isCustom = skillStr.indexOf('自得奇功') >= 0 || p.faction === '无门无派' || p.faction === '无名小派';
  /* __先天解锁：本预设是否带先天武学 */
  window.__先天可用 = /(^|·|\s)先天/.test(skillStr);

  if (isCustom) {
    // 自得奇功：切换到自定义栏，解析武学并填充
    document.getElementById('skill-type').value = 'custom';
    updateSkillInput();
    // 预设武学描述

    // 解析 "自得奇功·后天内功《汉宫秋》、自得奇功·后天掌法《桃花扇》、..." 或 "后天刀法《飞天御剑流》、..."
    var customs = [];
    skillStr.split('、').forEach(function(part) {
      part = part.trim().replace(/^自得奇功[··]?\s*/, '');
      var m = part.match(/^(.+?)《([^》]+)》$/);
      if (m) {
        var gradeType = m[1].trim();
        var gm = gradeType.match(/^(不入流|三品|二品|一品|后天|先天)(.+)$/);
        var sname = m[2].trim();
        customs.push({
          name: sname,
          grade: gm ? gm[1] : '三品',
          type: gm ? gm[2] : '内功',
          desc: PRESET_DESCS[sname] || ''
        });
      }
    });
    if (customs.length){fillCustomSkills(customs);if(['重瞳遗孤','退婚觉凤','黄粱一梦','星海溯古','月下双生'].includes(key)){const levels367=String(p.profs||'').split(/[、,，]/);Array.from(document.querySelectorAll('#custom-skills .custom-skill-row')).forEach((r,i)=>{const level=r.querySelector('.cs-prof');if(level)level.value=levels367[i]||'皮毛';if(['重瞳','天凤血','万物情理'].includes(r.querySelector('.cs-name')?.value)&&level){level.value='圆满';level.disabled=true;}});}}
  } else {
    // 宗门传承：切换到下拉栏，解析武学并选中
    document.getElementById('skill-type').value = 'auto';
    updateSkillInput();
    var skills = skillStr.split('、').map(function(s) { return s.trim(); }).filter(function(s) { return s; });
    var s1 = document.getElementById('skill-1');
    var s2 = document.getElementById('skill-2');
    var s3 = document.getElementById('skill-3');
    if (s1 && skills[0]) { refreshSelects(); s1.value = skills[0]; }
    if (s2 && skills[1]) { refreshSelects(); s2.value = skills[1]; }
    if (s3 && skills[2]) { refreshSelects(); s3.value = skills[2]; }
    refreshSelects();
    updateSkillValue();
  }

  syncOpeningRealm421();syncPresetMartial455();
  // 高亮提示玩家填写
  ['n','age','nick','look'].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) { el.style.borderColor = '#a81c1c'; el.placeholder = '← 请填写'; }
  });
}

