function confirmRemoval(title, message, action) {
  return new Promise(resolve => {
    const dialog = document.createElement('dialog');
    dialog.className = 'dsh-removal';
    dialog.setAttribute('aria-label', title);
    const heading = document.createElement('h3'), detail = document.createElement('p'), bar = document.createElement('div');
    heading.textContent = title;
    detail.textContent = message;
    const cancel = document.createElement('button'), confirm = document.createElement('button');
    cancel.type = confirm.type = 'button';
    cancel.textContent = '取消';
    confirm.textContent = action;
    confirm.className = 'dsh-removal-action';
    const opener = document.activeElement;
    cancel.addEventListener('click', () => dialog.close());
    confirm.addEventListener('click', () => dialog.close('confirm'));
    dialog.addEventListener('click', e => {
      const rect = dialog.getBoundingClientRect();
      if (e.target === dialog && (e.clientX < rect.left || e.clientX > rect.right || e.clientY < rect.top || e.clientY > rect.bottom)) dialog.close();
    });
    dialog.addEventListener('close', () => {
      dialog.remove();
      if (opener?.isConnected) opener.focus({preventScroll:true});
      resolve(dialog.returnValue === 'confirm');
    }, {once:true});
    bar.append(cancel,confirm);
    dialog.append(heading,detail,bar);
    document.body.append(dialog);
    if (typeof dialog.showModal !== 'function') {
      dialog.remove();
      resolve(window.confirm(title+'\n'+message));
      return;
    }
    dialog.showModal();
    cancel.focus({preventScroll:true});
  });
}

