    try {name=JSON.parse(saved)?.n||'';} catch {}
    if(!await confirmRemoval('焚毁开局卷宗？','卷宗 '+n+(name?'「'+name+'」':'')+' 中保存的开局人物将被删除。','确认焚卷'))return;
    if(localStorage.getItem(key)!==saved){updateSlotUI();alert('这份卷宗已变动，请核对后再焚卷。');return;}
