                }
            }, 100); /* 增加极微小的延迟，确保 DOM 和酒馆消息体已完全同步 */
        }

        function startPanel() { document.querySelectorAll('.love-content').forEach(function(_el) { init(_el); }); }
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', startPanel, { once: true });
        } else {
            startPanel();
        }

        })();
