    <script>
        (function() {

        function getMessageData() {
            try {
                var chatMessages = getChatMessages(getCurrentMessageId());
                if (chatMessages && chatMessages.length > 0) {
                    return chatMessages[0].message;
                }
            } catch (e) { console.error("获取消息API失败", e); }
            return null;
        }

        function parseData(messageText) {
            var result = {};
            var scope = messageText;
            /* [多份修复] messageText 已是本容器的块内容 */

            var cleanText = scope
                .replace(/<[^>]+>/g, ' ')
                .replace(/［/g, '[')
                .replace(/］/g, ']')
                .replace(/｜/g, '|');

            function extractValue(keyword) {
                var reg = new RegExp("(?<!特殊)" + keyword + "\\s*[\\|:：]\\s*([^\\]\\n]+)", "i");
                var match = cleanText.match(reg) || scope.match(reg);
                if (match && match[1]) {
                    return match[1].trim().replace(/<\/?.*$/, '').replace(/^\[|\]$/g, '').trim();
                }
                return null;
            }

            var fields = ['宝物名','品级','类别','图标','由来','效果','点评'];
            var any = false;
            fields.forEach(function (f) {
                var v = extractValue(f);
                if (v) { result[f] = v; any = true; }
            });
            if (any) return result;

            var brackets = [];
            var bracketReg = /\[([^\]\n]+)\]/g;
            var bm;
            while ((bm = bracketReg.exec(scope)) !== null) {
                if (bm[1] && bm[1].trim()) brackets.push(bm[1].trim());
            }
            if (brackets.length >= 2) {
                result['宝物名'] = brackets[0];
                result['品级'] = brackets[1];
                if (brackets.length >= 3) result['类别'] = brackets[2];
                if (brackets.length >= 4) result['图标'] = brackets[3];
                if (brackets.length >= 5) result['由来'] = brackets[4];
                if (brackets.length >= 6) result['效果'] = brackets[5];
                if (brackets.length >= 7) result['点评'] = brackets[6];
            }
            return result;
        }

        /* 品级 → 装饰符文与光效 */
        var RUNES = { '一品': '❖', '后天': '✦', '先天': '☯' };
        var META = { '一品': '青玉灵光 · 千年奇珍', '后天': '鎏金宝光 · 镇国奇物', '先天': '紫金神光 · 造化之物' };

        function renderPage(data,_el) {
            var rank = data['品级'] || '一品';
            var rk = ['一品','后天','先天'].indexOf(rank) >= 0 ? rank : '一品';
            var icon = data['图标'] || '✨';
            var name = data['宝物名'] || '无名奇珍';
            var cat = data['类别'] || '';
            var origin = data['由来'] || '';
            var effect = data['效果'] || '';
            var quote = data['点评'] || '此宝有灵。';

            var speaker = '', quoteText = quote;
            var colonIdx = quote.indexOf('：');
            if (colonIdx === -1) colonIdx = quote.indexOf(':');
            if (colonIdx > 0) { speaker = quote.substring(0, colonIdx); quoteText = quote.substring(colonIdx + 1); }

            var rune = RUNES[rk] || '❖';

            var html = `
                <div class="gold-frame"></div>
                <div class="halo"></div>
                <div class="particle pt-1"></div>
                <div class="particle pt-2"></div>
                <div class="particle pt-3"></div>
                <div class="particle pt-4"></div>
                <div class="particle pt-5"></div>
                <div class="particle pt-6"></div>
                <div class="rune rn-1">${rune}</div>
                <div class="rune rn-2">${rune}</div>
                <div class="rune rn-3">${rune}</div>
                <div class="rune rn-4">${rune}</div>

                <div class="content">
                    <div class="head">
                        <div class="icon-box">${icon}</div>
                        <div class="treasure-name">${name}</div>
                        <div class="treasure-meta">
                            <span class="rank-label meta-${rk}">${rk}</span>
                            ${cat ? ' · ' + cat : ''}
                            ${META[rk] ? ' · ' + META[rk] : ''}
                        </div>
                    </div>

                    ${origin ? '<div class="origin-box"><span class="origin-label">由来</span>' + origin + '</div>' : ''}

                    ${effect ? '<div class="effect-box"><span class="effect-label">宝效</span>' + effect + '</div>' : ''}

                    <div class="quote-box">
                        <span class="quote-label">点评</span>
                        <span class="quote-speaker">${speaker}</span><span class="quote-text">${quoteText}</span>
                    </div>
                </div>
            `;
            var el = _el;
            el.className = 'treasure-container rk-' + rk;
            el.innerHTML = html;
        }

        function init(_el) {
            setTimeout(function() {
                try {
                    /* [多份修复] 改为从自身容器读取本份原始块，避免二次取楼层导致多份渲染同一内容 */
                    var _src = _el ? _el.querySelector('.raw-src') : null;
                    var messageText = _src ? _src.content.textContent.trim() : '';
                    if (!messageText) {
                        _el.innerHTML =
                            '<div class="treasure-container" style="padding:30px 16px;"><div class="loading">❌ 无法获取消息内容，请稍后再试</div></div>';
                        return;
                    }
                    renderPage(parseData(messageText), _el);
                } catch (error) {
                    console.error("错误:", error);
                    _el.innerHTML =
                        '<div class="treasure-container" style="padding:30px 16px;"><div class="loading">❌ 鉴宝失败：' + error.message + '</div></div>';
                }
            }, 100);
        }

        function startPanel() { document.querySelectorAll('.treasure-content').forEach(function(_el) { init(_el); }); }
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', startPanel, { once: true });
        } else {
            startPanel();
        }

        })();
    </script>
</body>
</html>
