<script>
(function(){
  try{
    /* ── 块内自定位（同一消息可有多块，禁用 id 与 getElementById）──
       ① 优先 document.currentScript 的相邻兄弟
       ② 兜底：取正文里【最后一个未渲染】的 .byj 与其后的 .byj-raw */
    var s = document.currentScript, card = null, rawEl = null;
    if (s && s.previousElementSibling && s.previousElementSibling.previousElementSibling) {
      rawEl = s.previousElementSibling; card = rawEl.previousElementSibling;
      if (!(card && card.classList && card.classList.contains('byj'))) { card = null; rawEl = null; }
    }
    if (!card) {
      var 块们 = document.querySelectorAll('.byj:not([data-byj-done])');
      card = 块们.length ? 块们[块们.length - 1] : null;
      if (card) rawEl = card.nextElementSibling;
    }
    if (!card || !rawEl) return;
    card.setAttribute('data-byj-done','1');
    var kind = "$1";
    if (kind === "芳闻") card.classList.add('fang');
    card.querySelector('.kind').textContent = (kind === "芳闻") ? "群 芳 谱 传 闻" : "十 大 恶 人 传 闻";
    var raw = (rawEl.textContent || "").trim();
    var who = "", idx = "", body = raw;
    var m = raw.match(/^《([^》]*)》\s*([\s\S]*)$/);
    if (m) {
      var 头 = m[1].split("·");
      if (头.length >= 2) who = 头[1];
      if (头.length >= 3) idx = 头[2];
      body = m[2];
    }
    body = body.replace(/^[（(]占位内容[:：]?/, "[（占位）").trim();
    card.querySelector('.who').textContent = who || "佚名";
    card.querySelector('.idx').textContent = idx ? ("　" + idx) : "";
    card.querySelector('.body').textContent = body || "（空）";
  }catch(e){
    try{ var c = document.querySelector('.byj:not([data-byj-done])'); if(c) c.querySelector('.body').textContent = "（传闻渲染失败）"; }catch(e2){}
  }
})();
</script>

</body></html>

