  .cr-meta{font-size:.72em;line-height:1.4;letter-spacing:2px;color:#b9b9b9;margin-top:2px;}

  .cr-stage{position:relative;z-index:3;display:flex;overflow:hidden;}
  .cr-who{flex:1;position:relative;display:flex;flex-direction:column;justify-content:center;
    padding:14px 22px;transform:skewX(-18deg);overflow:hidden;}
  .cr-who>.cr-in{transform:skewX(18deg);position:relative;z-index:5;}
  .cr-who-l{background:#151515;color:#ededed;margin-left:-38px;padding-left:50px;border-right:2px solid #000;}
  .cr-who-r{background:#f0f0f0;color:#111;margin-right:-38px;padding-right:50px;border-left:2px solid #000;}
  .cr-who-l>.cr-in{text-align:right;padding-right:26px;}
