  .cr-tag{display:inline-block;font-size:.72em;line-height:1.6;letter-spacing:4px;padding:0 7px;margin-bottom:3px;}
  .cr-who-l .cr-tag{color:#f0f0f0;border:1px solid #6a6a6a;background:rgba(255,255,255,.08);}
  .cr-who-r .cr-tag{color:#111;border:1px solid #8a8a8a;background:rgba(0,0,0,.06);}
  .cr-name{font-family:'KaiTi','STKaiti','Ma Shan Zheng',cursive;font-size:1.9em;line-height:1.1;letter-spacing:4px;margin-bottom:2px;}
  .cr-who-l .cr-name{text-shadow:2px 2px 6px rgba(0,0,0,.85);}
