  .cr-realm{font-size:.74em;line-height:1.5;letter-spacing:1px;}
  .cr-who-l .cr-realm{color:#a8a8a8;} .cr-who-r .cr-realm{color:#5c5c5c;}
  .cr-realm i{font-style:normal;margin-left:8px;}
  .cr-who-l .cr-realm i{color:#e6c9c9;} .cr-who-r .cr-realm i{color:#1a1a1a;}
  .cr-cr{font-size:1.55em;line-height:1.1;letter-spacing:2px;margin-top:3px;font-weight:700;}
  .cr-who-l .cr-cr{color:#f0dda6;} .cr-who-r .cr-cr{color:#8a6a2a;}
