    font-family:'KaiTi','STKaiti',cursive;font-size:1.02em;line-height:1.5;letter-spacing:5px;
    color:#f6e6b4;background:linear-gradient(180deg,rgba(200,165,90,.2),rgba(200,165,90,.05));
    border:1px solid #a8884a;text-shadow:0 0 7px rgba(216,180,100,.5);}
  .cr-tier::before,.cr-tier::after{content:'\2756';position:absolute;top:50%;transform:translateY(-50%);color:#c8a55a;font-size:.6em;}
  .cr-tier::before{left:8px;} .cr-tier::after{right:8px;}
  .cr-tiersub{font-size:.72em;color:#a8905c;margin-top:2px;text-align:center;letter-spacing:1px;}
  .cr-bal{position:relative;margin:5px 12px 0;height:7px;background:#2a2118;border:1px solid #6b5730;overflow:hidden;}
  .cr-bal::before{content:'';position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:#c8a55a;z-index:3;}
  .cr-bal i{position:absolute;top:0;bottom:0;background:linear-gradient(180deg,#f0dda6,#b8923f);}

  .cr-think{margin:10px 12px 4px;border:1px solid rgba(151,107,53,.4);border-top:2px solid #8e6333;
    background:linear-gradient(90deg,rgba(156,111,58,.08),transparent);line-height:1.7;}
  .cr-think summary{cursor:pointer;letter-spacing:.18em;padding:7px 12px;color:#6a4a2a;font-size:.9em;font-family:'KaiTi','STKaiti',serif;}
  .cr-think p{margin:0;padding:8px 12px;white-space:pre-wrap;overflow-wrap:anywhere;color:#3a3020;font-size:.78em;line-height:1.7;border-top:1px dashed rgba(151,107,53,.3);}
  .cr-think[hidden]{display:none;}

  .cr-clash{position:relative;z-index:3;display:flex;background:#181310;border-top:1px solid #5a4a28;}
  .cr-clash>div{flex:1;padding:6px 14px;font-size:.82em;line-height:1.5;}
