  .cr-clash .r{color:#e8d7a8;text-align:right;border-left:1px solid #5a4a28;}
  .cr-clash span::before{content:'\300C';opacity:.55;} .cr-clash span::after{content:'\300D';opacity:.55;}
  .cr-foot{position:relative;z-index:3;border-top:2px solid #111;padding:5px 0 7px;text-align:center;
    background:#f7f5f0;font-family:'KaiTi','STKaiti',cursive;font-size:.76em;line-height:1.3;letter-spacing:8px;color:#3a3a3a;}
  .cr-hidden{display:none;}

  @media (max-width:600px){
    .cr-wrap{font-size:14px;margin:8px 0;border-top-width:3px;border-bottom-width:3px;}
    .cr-head{padding:5px 6px 6px;}
    .cr-title{font-size:1.4em;letter-spacing:9px;padding-left:9px;}
    .cr-meta{font-size:.7em;letter-spacing:0;}
    .cr-who{padding:9px 8px;transform:skewX(-12deg);}
    .cr-who>.cr-in{transform:skewX(12deg);}
    .cr-who-l{margin-left:-18px;padding-left:26px;}
    .cr-who-r{margin-right:-18px;padding-right:26px;}
    .cr-who-l>.cr-in{padding-right:14px;}
    .cr-who-r>.cr-in{padding-left:14px;}
    .cr-tag{font-size:.68em;letter-spacing:2px;padding:0 4px;}
    .cr-name{font-size:1.3em;letter-spacing:2px;}
    .cr-realm{font-size:.7em;}
    .cr-cr{font-size:1.25em;}
    .cr-arts{font-size:.68em;}
    .cr-taunt{font-size:.78em;}
    .cr-badge{width:36px;height:36px;font-size:1.25em;line-height:32px;border-width:1px;}
    .cr-rgrid{grid-template-columns:1fr 1fr 1fr;}
    .cr-rcell{padding:5px 5px 4px;}
    .cr-diffnum{font-size:1.25em;}
    .cr-tier{font-size:.86em;letter-spacing:3px;padding:1px 18px 2px;}
    .cr-think p{font-size:.74em;}
    .cr-clash>div{padding:5px 8px;font-size:.76em;}
    .cr-foot{font-size:.7em;letter-spacing:4px;}
  }
</style>
