  .cr-who-r .cr-member{color:#2a2a2a;}
  .cr-who-l .cr-member .m-cr{color:#f0dda6;}
  .cr-who-r .cr-member .m-cr{color:#8a6a2a;}
  .cr-who-l .cr-member .m-hpmp{color:#9a9a9a;}
  .cr-who-r .cr-member .m-hpmp{color:#6a6a6a;}
  .cr-badge{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:54px;height:54px;
    background:#b22222;color:#fff;font-family:'KaiTi','STKaiti',cursive;
    font-size:1.9em;line-height:50px;text-align:center;
    border-radius:4px;border:2px solid #8b0000;
    box-shadow:0 5px 15px rgba(0,0,0,.55),inset 0 0 15px rgba(100,0,0,.85);
    outline:1px dashed rgba(255,255,255,.42);outline-offset:-4px;z-index:15;}

  .cr-order{position:relative;z-index:3;background:rgba(255,255,255,.66);border-top:2px solid #111;padding:6px 12px 8px;}
  .cr-orderhead{position:relative;text-align:center;font-size:.72em;letter-spacing:6px;color:#3a3a3a;margin-bottom:4px;}
  .cr-orderhead::before,.cr-orderhead::after{content:'';position:absolute;top:50%;width:20%;height:1px;background:#c4c4c4;}
  .cr-orderhead::before{left:0;} .cr-orderhead::after{right:0;}
  .cr-orderrow{display:flex;align-items:center;gap:8px;padding:4px 2px;border-bottom:1px dotted rgba(0,0,0,.22);font-size:.8em;}
  .cr-orderrow:last-child{border-bottom:none;}
  .cr-orderrow .o-idx{flex:0 0 24px;text-align:center;font-family:'KaiTi','STKaiti',cursive;font-size:1.05em;color:#b22222;font-weight:700;}
  .cr-orderrow .o-name{font-family:'KaiTi','STKaiti',serif;letter-spacing:1px;color:#111;overflow-wrap:anywhere;}
  .cr-orderrow .o-side{flex:0 0 auto;font-size:.85em;color:#8a6a2a;letter-spacing:1px;}
  .cr-orderrow .o-cr{flex:1;text-align:right;font-weight:700;color:#3a3a3a;white-space:nowrap;}
  .m-aoe{display:inline-block;font-size:.85em;line-height:1.5;padding:0 5px;margin-left:2px;color:#f6e6b4;
    background:#181310;border:1px solid #a8884a;border-radius:2px;white-space:nowrap;letter-spacing:0;}

  .cr-sum{position:relative;z-index:3;background:#181310;border-top:2px solid #8a6f38;
    background-image:repeating-linear-gradient(90deg,rgba(200,165,90,.05) 0 2px,transparent 2px 7px);
    color:#d8c082;padding:7px 13px 8px;}
  .cr-sumrow{display:flex;gap:9px;font-size:.76em;line-height:1.5;}
  .cr-sumrow i{font-style:normal;color:#8a7a58;letter-spacing:2px;flex:0 0 auto;}
  .cr-sumrow span{color:#e8d7a8;overflow-wrap:anywhere;}

  .cr-think{margin:10px 12px 4px;border:1px solid rgba(151,107,53,.4);border-top:2px solid #8e6333;
    background:linear-gradient(90deg,rgba(156,111,58,.08),transparent);line-height:1.7;}
  .cr-think summary{cursor:pointer;letter-spacing:.18em;padding:7px 12px;color:#6a4a2a;font-size:.9em;font-family:'KaiTi','STKaiti',serif;}
  .cr-think p{margin:0;padding:8px 12px;white-space:pre-wrap;overflow-wrap:anywhere;color:#3a3020;font-size:.78em;line-height:1.7;border-top:1px dashed rgba(151,107,53,.3);}
  .cr-think[hidden]{display:none;}

  .cr-clash{position:relative;z-index:3;display:flex;background:#181310;border-top:1px solid #5a4a28;}
  .cr-clash>div{flex:1;padding:6px 14px;font-size:.82em;line-height:1.5;}
  .cr-clash>div>span{display:block;overflow-wrap:anywhere;}
  .cr-clash .l{color:#e8d7a8;text-align:left;}
  .cr-clash .r{color:#e8d7a8;text-align:right;border-left:1px solid #5a4a28;}
  .cr-clash span::before{content:'\300C';opacity:.55;} .cr-clash span::after{content:'\300D';opacity:.55;}
  .cr-foot{position:relative;z-index:3;border-top:2px solid #111;padding:5px 0 7px;text-align:center;
    background:#f7f5f0;font-family:'KaiTi','STKaiti',cursive;font-size:.76em;line-height:1.3;letter-spacing:8px;color:#3a3a3a;}
  .cr-hidden{display:none;}

  @media (max-width:600px){
    .cr-wrap{font-size:14px;margin:8px 0;border-top-width:3px;border-bottom-width:3px;}
    .cr-head{padding:5px 6px 6px;}
    .cr-title{font-size:1.4em;letter-spacing:9px;padding-left:9px;}
    .cr-meta{font-size:.7em;letter-spacing:0;}
    .cr-who{padding:9px 8px;transform:skewX(-12deg);}
    .cr-who>.cr-in{transform:skewX(12deg);}
    .cr-who-l{margin-left:-18px;padding-left:26px;}
    .cr-who-r{margin-right:-18px;padding-right:26px;}
    .cr-who-l>.cr-in{padding-right:13px;}
    .cr-who-r>.cr-in{padding-left:13px;}
    .cr-tag{font-size:.68em;letter-spacing:2px;padding:0 4px;}
    .cr-teamname{font-size:1em;letter-spacing:1px;}
    .cr-member{font-size:.72em;}
    .cr-badge{width:36px;height:36px;font-size:1.25em;line-height:32px;border-width:1px;}
    .cr-orderrow{font-size:.72em;gap:5px;padding:3px 1px 4px;}
    .cr-orderrow .o-idx{flex-basis:20px;}
    .cr-sum{padding:6px 10px 7px;}
    .cr-sumrow{font-size:.72em;gap:6px;}
    .cr-think p{font-size:.74em;}
    .cr-clash>div{padding:5px 8px;font-size:.76em;}
    .cr-foot{font-size:.7em;letter-spacing:4px;}
  }
</style>
</head>
<body>
<div class="cr-wrap">
  <template class="raw-src">$1</template>
  <div class="cr-head">
    <div class="cr-title">群 战</div>
    <div class="cr-meta"><span class="cr-place">江湖</span><span class="cr-sep"> · </span><span class="cr-time"></span><span class="cr-sep2"> · </span><span class="cr-terrain"></span></div>
  </div>
  <div class="cr-missing" hidden></div>
  <div class="cr-stage">
    <div class="cr-who cr-who-l"><div class="cr-in">
      <div class="cr-tag">我 方</div>
      <div class="cr-teamname gr-l-name"></div>
      <div class="gr-l-list"></div>
    </div></div>
    <div class="cr-badge">阵</div>
    <div class="cr-who cr-who-r"><div class="cr-in">
      <div class="cr-tag">敌 方</div>
      <div class="cr-teamname gr-r-name"></div>
      <div class="gr-r-list"></div>
    </div></div>
  </div>
  <div class="cr-order">
    <div class="cr-orderhead">行 动 顺 序 · CR 高 者 先 出 手</div>
    <div class="gr-order-list"></div>
  </div>
  <div class="cr-sum">
    <div class="cr-sumrow"><i>战 局</i><span class="gr-sum1"></span></div>
    <div class="cr-sumrow"><i>意 志</i><span class="gr-sum2"></span></div>
    <div class="cr-sumrow"><i>退 路</i><span class="gr-sum3"></span></div>
  </div>
  <details class="cr-think" hidden><summary>⚔️ 战斗思考 · 点击展开</summary><p class="cr-thinktext"></p></details>
  <div class="cr-clash">
    <div class="l"><span class="gr-l-mid"></span></div>
    <div class="r"><span class="gr-r-mid"></span></div>
  </div>
  <div class="cr-foot">大 凉 龙 虎 录</div>
</div>
<script>/* =========================================================
 * 大凉龙虎传 · CR 确定性计算器（纯函数，无 DOM 依赖）
 * 用途：把战力数值从「AI 心算」改为「脚本固定计算」
 * ========================================================= */
(function (root) {
  'use strict';

  var REALM = {
    '无修为': { b: 1, l: 0, hp: 60, mp: 45 },
    '一境锻骨': { b: 3, l: 1, hp: 60, mp: 45 },
    '二境筑基': { b: 6, l: 2, hp: 60, mp: 45 },
    '三境明气': { b: 11, l: 3, hp: 60, mp: 45 },
    '四境开窍': { b: 20, l: 4, hp: 90, mp: 75 },
    '五境八关_一关开': { b: 90, l: 5, hp: 120, mp: 105 },
    '五境八关_二关休': { b: 95, l: 5, hp: 120, mp: 105 },
    '五境八关_三关生': { b: 100, l: 5, hp: 120, mp: 105 },
    '五境八关_四关伤': { b: 110, l: 5, hp: 150, mp: 135 },
    '五境八关_五关杜': { b: 112, l: 5, hp: 150, mp: 135 },
    '五境八关_六关景': { b: 115, l: 5, hp: 150, mp: 135 },
    '五境八关_七关死': { b: 120, l: 5, hp: 180, mp: 165 },
    '五境八关_八关惊': { b: 125, l: 5, hp: 180, mp: 165 },
    '气海_初入': { b: 160, l: 6, hp: 300, mp: 240 },
    '气海_中凝': { b: 180, l: 6, hp: 360, mp: 300 },
    '气海_满盈': { b: 210, l: 6, hp: 420, mp: 360 },
    '七境抱丹': { b: 420, l: 7, hp: 720, mp: 540 },
    '抱丹魔神': { b: 480, l: 7, hp: 720, mp: 540 },  // 苏家神剑真实境界：抱丹境的魔神级剑灵（重伤时按伤势系数打折，约 CR 669）
    '八境破星': { b: 1000, l: 8, hp: 1200, mp: 780 },
    '九境宏愿': { b: 5000, l: 9, hp: 2400, mp: 1500 }
  };

  var GRADE = { '不入流': 4, '三品': 11, '二品': 18, '一品': 32, '后天': 56, '先天': 70 };
  var PROF = { '皮毛': 0.10, '粗通': 0.30, '登堂': 0.60, '入室': 1.00, '圆满': 1.50 };
  var YI = { '无意境': 1.0, '初境_意': 1.2, '中境_明意': 1.5, '上境_极意': 1.6, '极境_真意': 1.8 };
  var ARMOR_HP = { '不入流': 0, '三品': 20, '二品': 40, '一品': 80, '后天': 150, '先天': 300 };
  var HENGLIAN_HP = { '不入流': 0, '三品': 30, '二品': 60, '一品': 90, '后天': 150, '先天': 240 };
  var NEIGONG_MP = { '不入流': 0, '三品': 24, '二品': 36, '一品': 60, '后天': 90, '先天': 150 };
  var BAO = { '一品': 12, '后天': 24, '先天造化': 50 };
  var PRESS = { 1: 2, 2: 5, 3: 12, 4: 25, 5: 50, 6: 100, 7: 200, 8: 500, 9: 99999 };
  var GRADE_ORDER = ['不入流', '三品', '二品', '一品', '后天', '先天'];

  function r2(x) { return Math.round(x * 100) / 100; }
  function num(v) { var s = String(v == null ? '' : v).trim(); var m = s.match(/^[+-]?\d+(\.\d+)?$/); return m ? parseFloat(m[0]) : 0; }
  function topGrade(list) {
    var best = '不入流';
    for (var i = 0; i < list.length; i++) {
      if (GRADE_ORDER.indexOf(list[i].grade) > GRADE_ORDER.indexOf(best)) best = list[i].grade;
    }
    return best;
  }
  function hpCoef(ratio) {
    if (ratio <= 0) return 0;
    if (ratio >= 0.76) return 1.00;
    if (ratio >= 0.51) return 0.90;
    if (ratio >= 0.26) return 0.75;
    return 0.55;
  }
  function tierOf(d) {
    var a = Math.abs(d);
    if (a <= 10) return '势均力敌';
    if (a <= 25) return d >= 0 ? '略占上风' : '略处下风';
    if (a <= 50) return d >= 0 ? '稳占上风' : '明显劣势';
    if (a <= 75) return d >= 0 ? '全面压制' : '强弱悬殊';
        return d >= 0 ? '彻底碾压' : '毫无悬念';
  }
  function yiMul(s) {
    if (YI[s]) return YI[s];
    if (/极境/.test(s)) return 1.8;
    if (/上境/.test(s)) return 1.6;
    if (/中境/.test(s)) return 1.5;
    if (/初境/.test(s)) return 1.2;
    return 1.0;
  }

  function calcArts(listStr) {
    var groups = { '内功': [], '横练': [], '轻功': [], '外功': [], '其他': [] };
    var total = 0, lines = [];
    if (listStr) {
      var items = listStr.split(';');
      for (var i = 0; i < items.length; i++) {
        var seg = items[i].trim();
        if (!seg) continue;
        var p = seg.split(':');
        if (p.length < 4) continue;
        var type = p[0].trim(), name = p[1].trim(), grade = p[2].trim(), prof = p[3].trim();
        var gv = GRADE[grade], pv = PROF[prof];
        if (gv == null || pv == null) continue;
        var val = r2(gv * pv);
        if (!groups[type]) groups[type] = [];
        groups[type].push({ name: name, grade: grade, prof: prof, val: val });
      }
    }
    var maxN = { '内功': 3, '横练': 3, '轻功': 2, '外功': 0, '其他': 2 }; // 外功=0：外功不计入战前武学加值，只在出招时由AI逐回合体现
    var ratios = [1.0, 0.5, 0.25];
    for (var t in groups) {
      var list = groups[t].sort(function (a, b) { return b.val - a.val; });
      var n = Math.min(list.length, maxN[t]);
      for (var j = 0; j < n; j++) {
        var ratio = ratios[j];
        var contrib = r2(list[j].val * ratio);
        total = r2(total + contrib);
        lines.push(t + '《' + list[j].name + '》' + list[j].grade + '·' + list[j].prof +
          '(' + r2(list[j].val) + (j > 0 ? '×' + ratio : '') + ')');
      }
    }
    return { total: total, detail: lines.join('+'), groups: groups };
  }

  function calcPerson(inp) {
    inp = inp || {};
    var realmStr = String(inp.realm || '').replace(/\s+/g, '');
    var realmKey = realmStr;
    var ruhai = 1.0;
    // 气海境：兼容「气海_初入_八关」「八关气海_初入」「气海初入」「气海_初入」等顺序与分隔变体（非气海境界原样查表，不做任何替换）
    var m1 = realmStr.match(/^气海[_\s]?(初入|中凝|满盈)(?:[_\s]?(六关|七关|八关))?$/);
    if (m1) {
      realmKey = '气海_' + m1[1];
      var g1 = m1[2] || '';
      if (g1 === '六关') ruhai = 0.8;
      else if (g1 === '八关') ruhai = 1.2;
      else ruhai = 1.0;
    } else {
      var m2 = realmStr.match(/^(六关|七关|八关)气海[_\s]?(初入|中凝|满盈)$/);
      if (m2) {
        realmKey = '气海_' + m2[2];
        var g2 = m2[1];
        if (g2 === '六关') ruhai = 0.8;
        else if (g2 === '八关') ruhai = 1.2;
        else ruhai = 1.0;
      }
    }
    var r = REALM[realmKey] || REALM[realmStr] || { b: 0, l: 0, hp: 0, mp: 0 };
    var arts = calcArts(inp.arts);
    var yi = yiMul(inp.yi || '');
    var blade = num(inp.blade);
    var armorGrade = inp.armor || '';
    var armorHP = ARMOR_HP[armorGrade] || 0;
    var baoGrade = inp.bao || '';
    var bao = BAO[baoGrade] || 0;
    var injury = inp.injury || '无伤';
    var hpStr = String(inp.hpCur == null ? '' : inp.hpCur);
    var hpCur = num(hpStr.split('/')[0]);
    var mpCur = num(String(inp.mpCur == null ? '' : inp.mpCur).split('/')[0]);
    var hlTop = topGrade(arts.groups['横练'] || []);
    var ngTop = topGrade(arts.groups['内功'] || []);
    var hpMax = r.hp + (HENGLIAN_HP[hlTop] || 0) + armorHP;
    var mpMax = r.mp + (NEIGONG_MP[ngTop] || 0);
    // 【满状态兜底】无伤/满状态开局（injury 为空或无伤），当前 HP/MP 强制=上限（满血满蓝），防 AI 误填残缺血
    if (!injury || injury === '无伤') { hpCur = hpMax; mpCur = mpMax; }
    var hpRatio = hpMax > 0 ? hpCur / hpMax : 1;
    var hpMul = hpCoef(hpRatio);

    var bonusArts = num(inp.bonusArts);
    var bonusBlade = num(inp.bonusBlade);
    var core = (r.b + arts.total + bonusArts) * yi * ruhai * hpMul;
    var raw = core + blade + bao + bonusBlade;
    var finalCR = raw;
    var injNote = '−0';
    if (injury === '轻伤' || injury === '中毒') { finalCR = raw - 8; injNote = '−8'; }
    else if (injury === '重伤') { finalCR = raw * 0.7; injNote = '×0.7'; }
    else if (injury === '濒死') { finalCR = raw * 0.3; injNote = '×0.3'; }
    finalCR = Math.round(finalCR);

    // 【林清逸唯一例外】CR/HP/MP 恒定，禁止按境界公式计算（八境破星肉身但功力尽失）
    if (inp.name && inp.name.indexOf('林清逸') >= 0) {
      finalCR = 1500; hpMax = 1800; mpMax = 0; hpCur = 1800; mpCur = 0;
      hpRatio = 1; hpMul = 1; injNote = '−0';
    }

    return {
      name: inp.name || '', realm: realmStr, base: r.b, layer: r.l,
      artsTotal: arts.total, artsDetail: arts.detail, artsGroups: arts.groups,
      yi: yi, ruhai: ruhai, blade: blade, armorGrade: armorGrade, armorHP: armorHP,
      bao: bao, injury: injury, injNote: injNote,
      hpCur: hpCur, mpCur: mpCur, hpMax: hpMax, mpMax: mpMax,
      hpMul: hpMul, hpRatio: hpRatio, finalCR: finalCR,
      bonusArts: bonusArts, bonusBlade: bonusBlade
    };
  }

  // 一对一对比（压制 + 差值 + 档位）
  function calcBattle(A, B) {
    var press = { lowIsA: false, lowIsB: false, deduct: 0 };
    var hi = A.layer >= B.layer ? A.layer : B.layer;
    var lo = A.layer >= B.layer ? B.layer : A.layer;
    var X = hi - lo;
    if (X > 0) {
      var deduct = (PRESS[hi] || 0) * X * 0.5;
      if (A.layer < B.layer) { press.lowIsA = true; press.deduct = deduct; }
      else { press.lowIsB = true; press.deduct = deduct; }
    }
    var effA = A.finalCR, effB = B.finalCR;
    if (press.lowIsA) effA = Math.max(A.finalCR - press.deduct, 1);
    if (press.lowIsB) effB = Math.max(B.finalCR - press.deduct, 1);
    var delta = (effA - effB) / effB * 100;
    var tier = tierOf(delta);
    return { A: A, B: B, press: press, effA: effA, effB: effB, delta: delta, tier: tier };
  }

  function genProcess(A, B, bt) {
    function one(pre, c, eff) {
      var L = [];
      L.push(pre + '「' + c.name + '」：');
      L.push('  ①境界基数=' + c.base + '（' + c.realm + '）');
      L.push('  ②武学加值=' + c.artsDetail + '=' + r2(c.artsTotal));
      L.push('  ③意境=×' + c.yi);
      L.push('  ④入海根基=×' + c.ruhai);
      L.push('  ⑤兵装=兵刃+' + c.blade + '（防具' + (c.armorGrade || '无') + ' +' + c.armorHP + 'HP 不计CR）');
      L.push('  ⑥其他补正=+' + c.bao);
      L.push('  ⑥.5特效=武学' + (c.bonusArts > 0 ? '+' : '') + r2(c.bonusArts) + '（进乘区）＋兵装' + (c.bonusBlade > 0 ? '+' : '') + r2(c.bonusBlade) + '（不进乘区）');
      L.push('  ⑦伤势=' + c.injNote);
      L.push('  ⑧HP系数=×' + c.hpMul.toFixed(2) + '（' + c.hpCur + '/' + c.hpMax + '）');
      L.push('  ⑨最终CR=(' + c.base + '+' + r2(c.artsTotal) + (c.bonusArts ? '+' + r2(c.bonusArts) : '') + ')×' + c.yi + '×' + c.ruhai + '×' + c.hpMul.toFixed(2) + ' + ' + c.blade + (c.bonusBlade ? '+' + r2(c.bonusBlade) : '') + ' + ' + c.bao + ' ' + c.injNote + ' = ' + c.finalCR);
      var isA = (pre === '甲');
      if (bt.press.lowIsA && isA) L.push('  ⑩境界压制=−' + r2(bt.press.deduct) + ' → 有效CR=' + eff);
      else if (bt.press.lowIsB && !isA) L.push('  ⑩境界压制=−' + r2(bt.press.deduct) + ' → 有效CR=' + eff);
      else L.push('  ⑩境界压制=无（同层）');
      return L.join('\n');
    }
    var head = '【CR 计算过程】（脚本确定性计算）';
    var body = one('甲', A, bt.effA) + '\n' + one('乙', B, bt.effB);
    var duel = '【交战双方】' + A.name + '（' + A.realm + '｜最终CR ' + A.finalCR + '｜有效CR ' + bt.effA + '｜HP ' + A.hpCur + '/' + A.hpMax + '｜MP ' + A.mpCur + '/' + A.mpMax + '） 对 ' +
      B.name + '（' + B.realm + '｜最终CR ' + B.finalCR + '｜有效CR ' + bt.effB + '｜HP ' + B.hpCur + '/' + B.hpMax + '｜MP ' + B.mpCur + '/' + B.mpMax + '）';
    return head + '\n' + body + '\n' + duel;
  }

  function artsSummary(c) {
    var names = [];
