function 迁移时标输入(v){
  if(!v||typeof v!=='object')return v;
  function 合法(n){return (typeof n==='number'||typeof n==='string'&&n.trim()!=='')&&Number.isFinite(Number(n))&&Number(n)>=0;}
  var 时=Object.assign({},v.时间||{}),原=时.刻度;
  for(const k of ['刻度','上轮刻度'])if(!合法(时[k]))delete 时[k];
  if(!合法(原)&&v.当前时间)时.待迁移文本=String(v.当前时间);
  return Object.assign({},v,{时间:时});
}

