  entries.forEach((e,i)=>{if(!byName.has(e.name))byName.set(e.name,[]);byName.get(e.name).push(i);if(!byIdRows.has(e.id))byIdRows.set(e.id,[]);byIdRows.get(e.id).push(i);});
