const 兼容布尔值 = z.preprocess(value => {
  if (value === null || value === undefined) return false;
  if (typeof value === 'boolean') return value;
  const text = typeof value === 'string' ? value.trim().toLowerCase() : value;
  if ([true, 1, '1', 'true', '是', '开启', '开', 'on'].includes(text)) return true;
  if ([false, 0, '', '0', 'false', '否', '关闭', '关', 'off'].includes(text)) return false;
  return value;
}, z.boolean()).prefault(false);
