  const CSS = `
  .byj{--paper1:#efe4bd;--paper2:#e4d3a2;--paper3:#d8c48c;--edge:#b99a5e;--ink:#22201c;--soft:#4a443a}
  .byj *{box-sizing:border-box}
  .byj-plaque{position:fixed;left:24px;top:calc(50% - 140px);width:200px;z-index:2147483647 !important;
    pointer-events:auto !important;isolation:isolate;
    cursor:pointer;touch-action:none;user-select:none;filter:drop-shadow(0 6px 16px rgba(0,0,0,.5))}
  .byj-scroll{position:relative;width:200px;height:268px}
  .byj-scroll{pointer-events:auto}
  .byj-scroll .sc{position:absolute;inset:0;pointer-events:none}
  .byj-scroll .sc svg,.byj-scroll .sc *{pointer-events:none}
  .byj-scroll .sc svg{width:100%;height:100%;display:block;transform:scaleY(1.34);transform-origin:center}
  .byj-row{position:absolute;left:0;right:0;top:43%;display:flex;justify-content:center;align-items:center;
    gap:5px;z-index:3;pointer-events:none}
  .byj-row .t{height:38px;width:auto}
  .byj-row .t svg{display:block;height:100%;width:auto}
  .byj-row .t:nth-child(1){transform:translate(-4px,-6px) rotate(8deg)}
  .byj-row .t:nth-child(3){transform:translate(8px,6px)}
  .byj-panel{position:fixed;width:308px;z-index:2147483647 !important;pointer-events:auto !important;display:none;border-radius:7px;overflow:hidden;
    background:linear-gradient(158deg,var(--paper1),var(--paper2) 62%,var(--paper3));
    border:1px solid var(--edge);box-shadow:0 12px 34px rgba(0,0,0,.42);color:var(--ink);
    font-family:"Microsoft YaHei","PingFang SC","Hiragino Sans GB","Source Han Sans SC","Noto Sans CJK SC","WenQuanYi Micro Hei",system-ui,sans-serif}
  .byj-panel.on{display:block}
  .byj-panel .h{display:flex;align-items:center;justify-content:space-between;padding:9px 13px;
    border-bottom:1px solid rgba(120,95,55,.35);background:linear-gradient(180deg,rgba(255,255,255,.38),rgba(0,0,0,.03))}
  .byj-panel .h .ttl{font-size:17px;letter-spacing:5px}
  .byj-panel .h .x{cursor:pointer;padding:0 5px;color:var(--soft)}
  .byj-panel .b{padding:12px 14px 15px}
  .byj-r{margin:12px 0}
  .byj-lab{display:flex;justify-content:space-between;font-size:14px;letter-spacing:1px;margin-bottom:5px}
  .byj-lab .v{font-weight:700}
  .byj-panel input[type=range]{width:100%;accent-color:#8a6a3a}
  .byj-hint{font-size:12px;color:var(--soft);margin-top:3px}
  .byj-sep{height:1px;background:rgba(120,95,55,.3);margin:12px 0}
  .byj-st{font-size:13px;line-height:1.9;color:var(--soft);word-break:break-all}
  .byj-st b{color:var(--ink)}
