function formalTravelFields(text) {
  let source = String(text || '').trimStart();
  while (source) {
    const block = source.match(/^<(erii_draft|erii_outline|erii_memo|erii_theater|think|thinking|analysis|details|pre|code|festival_scene|baiyi_panel|pet_panel)\b[^>]*>/i);
    if (block) {
      const tags = new RegExp('<(/?)' + block[1] + '(?:\\s[^>]*)?>','gi');
      let depth = 0, token;
      while ((token = tags.exec(source))) {
        depth += token[1] ? -1 : 1;
        if (depth === 0) break;
      }
      if (!token) return null;
      source = source.slice(tags.lastIndex).trimStart();
      continue;
    }
    if (source.startsWith('<!--')) {
      const end = source.indexOf('-->', 4);
      if (end < 0) return null;
      source = source.slice(end + 3).trimStart();
      continue;
    }
    const fence = source.match(/^(`{3,}|~{3,})[^\r\n]*\r?\n/);
    if (fence) {
      const close = new RegExp('^[ \\t]{0,3}' + fence[1][0] + '{' + fence[1].length + ',}[ \\t]*\\r?$', 'gm');
      close.lastIndex = fence[0].length;
      if (!close.exec(source)) return null;
      source = source.slice(close.lastIndex).trimStart();
      continue;
    }
    // Older prefills supplied the opening draft tag outside the saved assistant text.
    const draftEnd = source.match(/<\/erii_draft\s*>/i);
    if (draftEnd && !/<(?:content|bbs_start|erii_draft)\b/i.test(source.slice(0,draftEnd.index))) {
      source = source.slice(draftEnd.index + draftEnd[0].length).trimStart();
      continue;
    }
    const title = source.match(/^(?:#{1,6}[ \t]*)?(?:【(?:时空页眉|场景卡)】|时空页眉|场景卡)[：: \t]*(?:\r?\n|(?=<scene_card\b))/);
    if (title) {source=source.slice(title[0].length).trimStart();continue;}
    break;
  }
  const header = source.match(/^<scene_card\b[^>]*>\s*([^<>]{1,1200})<\/scene_card\s*>/i);
  if (!header) return null;
  const fields = header[1].trim().split(/[|｜]/).map(part => part.trim());
  return fields.length >= 6 ? fields : null;
}
