function person(kind,name,evilRows){const key=canon(name),p=bank.characters.find(x=>x.kind===kind&&canon(x.name)===key);if(p&&p.enabled===true&&p.public===true&&p.rumors.every(r=>r.status==='approved')&&validRows(p.rumors))return p;
if(kind!=='恶闻')return null;const row=(evilRows||[]).find(r=>canon(r.姓名)===key&&r.状态==='在逃'&&r.替补===true);if(!row)return null;
const rumors=(row.传闻||[]).map((text,i)=>({id:'替补-'+row.id+'-'+(i+1),ordinal:i+1,text,status:'approved'}));return validRows(rumors)?{name:row.姓名,publicName:row.姓名,kind,rumors,scope:'主角附近'}:null;}
function eligible(kind,names,evilRows){return [...new Set((names||[]).map(canon))].filter(n=>person(kind,n,evilRows));}
function choose(kind,names,random,evilRows){const candidates=eligible(kind,names,evilRows);if(!candidates.length)return null;const p=person(kind,candidates[Math.floor(random()*candidates.length)],evilRows),r=p.rumors[Math.floor(random()*p.rumors.length)],publicName=p.publicName||p.name;return {版本:bank.version,类别:kind,人物:p.name,公开称呼:publicName,篇次:r.ordinal,条目:r.id,正文:r.text,帖头:'《'+(kind==='恶闻'?'十大恶人传闻':'群芳谱传闻')+'·'+publicName+'·其'+['零','一','二','三','四','五'][r.ordinal]+'》',位置范围:kind==='恶闻'?'主角附近':p.scope||p.province};}
function archive(previous,history){let result=Array.isArray(history)?copy(history):[];if(previous?.本轮键)for(const kind of ['恶闻','芳闻']){const item=previous[kind];if(item?.正文){const key=previous.本轮键+'|'+kind;if(!result.some(x=>x.记录键===key))result.push({...copy(item),记录键:key,输入楼:previous.用户楼});}}return result.slice(-8);}
return{canon,person,eligible,choose,archive,version:321};
}

