roved"}]},{"name":"玛尔法","kind":"芳闻","publicName":"玛尔法","enabled":true,"public":true,"province":"罗刹国","scope":"罗刹国","rumors":[{"id":"芳闻-玛尔法-1","ordinal":1,"text":"冻河泊的歇脚酒肆里，几个猎户正瞧着墙角那位眉淡面白的妇人。她穿着利落的灰白翻毛短袄，腰挎两柄雪色短刀，眼下正就着一盘干肉小口抿烈酒，半句闲话也不多说。","status":"approved"},{"id":"芳闻-玛尔法-2","ordinal":2,"text":"寒林镇大集边的马具铺外，那位短袄袖口扎紧的利落妇人正站在那儿。掌柜正按她的要求加固皮带扣子，她腰挎两把雪白短刀，抱着胳膊在一旁静静盯着工匠手艺。","status":"approved"},{"id":"芳闻-玛尔法-3","ordinal":3,"text":"碎冰关南面茶水摊的伙计念叨，有个面色寡淡的妇人正坐在长凳上歇脚。她腰间插着两把白晃晃的短刀，这会儿正拿粗布细细擦拭雪地靴上的泥浆，动作格外麻利。","status":"approved"},{"id":"芳闻-玛尔法-4","ordinal":4,"text":"白石城城门外的铁匠棚前，围着看热闹的人说那位眉眼寡淡的妇人正等铁料冷却。她一身灰白短袄，正抱臂倚着炉台，等着铁匠替她换新打好的防滑冰爪。","status":"approved"}]},{"name":"幽夫人","kind":"芳闻","publicName":"幽夫人","enabled":true,"public":true,"province":"蓬莱","scope":"蓬莱","rumors":[{"id":"芳闻-幽夫人-1","ordinal":1,"text":"瀛洲集市南街的药材铺掌柜正忙着赔笑，幽夫人这会儿黑纱覆面坐在铺内，垂眸翻看刚从深海采来的几株墨色毒珊瑚，周遭隐隐飘着甜腻异香，连路过的采药客都不敢大声喘气。","status":"approved"},{"id":"芳闻-幽夫人-2","ordinal":2,"text":"蓬莱岛深海采集场的栈桥边聚了不少船工，幽夫人身着奇异苗疆衣裙站在那儿，正由侍从端着瓷盅，亲手辨验几尾刚从深水捞起的斑斓海蛇，眼下谁也不敢近前打扰。","status":"approved"},{"id":"芳闻-幽夫人-3","ordinal":3,"text":"瀛洲主港的香料行门前微风送香，幽夫人今日正立在柜台前挑选南洋送来的干草药，指尖轻捻香料细细闻嗅，旁边的伙计恭恭敬敬地候着回话，引得不少茶客在门外张望。","status":"approved"},{"id":"芳闻-幽夫人-4","ordinal":4,"text":"方丈岛私港的一处临海茶棚里，幽夫人正倚在竹榻上漫不经心地品着凉茶，黑纱微动，目光落向外头货船卸下的几个大药箱，随行侍女正拿着账册在桌前向她轻声禀报。","status":"approved"}]},{"name":"阿朵骨","kind":"芳闻","publicName":"阿朵骨","enabled":true,"public":true,"province":"南疆","scope":"南疆","rumors":[{"id":"芳闻-阿朵骨-1","ordinal":1,"text":"黑水寨的神树石阶下，黑水部的大巫祭阿朵骨这会儿正给求药的族人分发驱虫草包。她颈上盘着那条黑斑大蟒，赤足踩在青石上，正神色温和地替身前的小童点涂雄黄。","status":"approved"},{"id":"芳闻-阿朵骨-2","ordinal":2,"text":"听采药的苗人说，阿朵骨大巫祭眼下正在百族药谷的石坊前挑拣药材。她身着五彩衣裳，正一边逗弄腕间的毒虫，一边同药农仔细比对刚采下来的几篓新鲜药草。","status":"approved"},{"id":"芳闻-阿朵骨-3","ordinal":3,"text":"雾瘴关的互市木楼边热闹得很，阿朵骨今日正赤足坐在二楼临街的竹榻上歇息。她脖颈缠着黑斑毒蟒，正垂眸打量楼下中原客商带来的各色干果与布匹。","status":"approved"},{"id":"芳闻-阿朵骨-4","ordinal":4,"text":"黑水寨寨门前的藤桥边，阿朵骨此刻正带着几名巫女检视进寨的背篓。她身前盘着臂粗的毒蟒，正低头核验过桥猎户带回的晒干药材，瞧着十分细致耐烦。","status":"approved"}]},{"name":"薇玛拉","kind":"芳闻","publicName":"薇玛拉","enabled":true,"public":true,"province":"南洋群岛","scope":"南洋群岛","rumors":[{"id":"芳闻-薇玛拉-1","ordinal":1,"text":"蒲甘城万塔的石阶前，白衣赤足的薇玛拉正坐在阴凉处，手里拿把小苇帚，帮看塔的老沙弥细细扫除佛龛石缝里的落叶，任凭香客来往也不抬头。","status":"approved"},{"id":"芳闻-薇玛拉-2","ordinal":2,"text":"蒲甘城门外的茶摊底下，那位长发散垂的白衣姑娘薇玛拉眼下正要了一碗清水歇脚，指尖正慢条斯理摩挲着颈上那串缺了木珠的旧链子。","status":"approved"},{"id":"芳闻-薇玛拉-3","ordinal":3,"text":"蒲甘城渡口边的水桥旁，薇玛拉正立在栈板上，替靠岸的采莲小童将一篓篓新鲜水白莲接上岸，整齐码在青石板边，引得过路行人都放慢了步子。","status":"approved"},{"id":"芳闻-薇玛拉-4","ordinal":4,"text":"蒲甘城外市集北头的药草棚前，持经人薇玛拉正驻足挑选驱热的苦草根，摊贩给她递过洗净的叶包，她正安静站在摊前等候称量。","status":"approved"}]},{"name":"阿玛雅","kind":"芳闻","publicName":"阿玛雅","enabled":true,"public":true,"province":"南洋群岛","scope":"南洋群岛","rumors":[{"id":"芳闻-阿玛雅-1","ordinal":1,"text":"巴石河口码头的石阶边，两臂刺满浪纹的阿玛雅正赤足踩在空鱼箱上，腰别两根藤木短棍，扯着嗓门替村里相熟的疍户跟收鱼贩子算账还价呢。","status":"approved"},{"id":"芳闻-阿玛雅-2","ordinal":2,"text":"素万城擂台旁的凉棚里，吕宋村邦的少头人阿玛雅正和几个南洋拳手拼桌，两根短棍横在桌角，她正拍着桌子同众人掷椰子壳赌酒，笑声极响亮。","status":"approved"},{"id":"芳闻-阿玛雅-3","ordinal":3,"text":"巴石河口大集市里的藤编摊前，短棍阿玛雅正叉着腰挑拣结实的藤皮绳，手里短棍上下晃悠着，跟铺子掌柜讨价还价，护短地替同村人多讨了两捆。","status":"approved"},{"id":"芳闻-阿玛雅-4","ordinal":4,"text":"蒲甘城南门外的河埠头边，阿玛雅正带着几个吕宋小伙蹲在栈桥上，手里拿短棍拨弄水里的浮木比试眼力，嘴里还在大声催促着船家快备缆绳。","status":"approved"}]},{"name":"巴月","kind":"芳闻","publicName":"巴月","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-巴月-1","ordinal":1,"text":"附近驿站的马料棚前，那位着短款豹皮装、手臂绘满青纹的巴月姑娘正拿胡萝卜喂驮马。她腰间盘着兽筋长鞭，正跟伙计仔细打听进深山打猎的路径呢。","status":"approved"},{"id":"芳闻-巴月-2","ordinal":2,"text":"街口铁匠铺子外，巴月正蹲在磨石旁试她长鞭上的铜环。她一身兽皮猎装引得不少人张望，她倒浑不在意，正挽着袖子催铁匠赶快给她的猎刀淬火。","status":"approved"},{"id":"芳闻-巴月-3","ordinal":3,"text":"听闻附近野味集市里热闹得很，巴月正扛着两头山鸡跟皮货掌柜讨价还价。她小腿上绘着山熊战纹，说话嗓门极脆，这会儿还在货摊前比划毛皮成色。","status":"approved"},{"id":"芳闻-巴月-4","ordinal":4,"text":"镇外老槐树下的茶摊边，巴月正踩着长凳喝大碗酽茶，随身的兽筋长鞭搭在桌角。邻桌的几个老猎户正跟她讨教鞣皮子的窍门，她聊得兴起，眼下还没打算动身。","status":"approved"}]},{"name":"蓝鸯","kind":"芳闻","publicName":"蓝鸯","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-蓝鸯-1","ordinal":1,"text":"镇子水井旁的凉棚下，叮叮当当一阵银饰脆响，原是蓝鸯姑娘正教几个孩童翻花绳。她腕上挂满精致小银铃，笑声清脆，这会儿正从兜里抓糖果分给大家。","status":"approved"},{"id":"芳闻-蓝鸯-2","ordinal":2,"text":"附近草药铺子前，一身苗银叮当晃动的蓝鸯正挑拣掌柜新晒的草药。她生得古灵精怪，偏爱辨认那些带刺的古怪根茎，这会儿还在跟药铺伙计磨蹭着要买整筐。","status":"approved"},{"id":"芳闻-蓝鸯-3","ordinal":3,"text":"渡口边上的糖画摊子前围了不少人，那位叫蓝鸯的苗服姑娘正晃着满头银饰等她的糖兔子。转盘恰好转到了金凤，她乐得直拍手，催着摊贩快些浇糖浆。","status":"approved"},{"id":"芳闻-蓝鸯-4","ordinal":4,"text":"街心小酒馆的二楼窗边，蓝鸯正托着下巴看街景，身上的银饰随着动作闪闪发亮。她桌上摆着几碟甜渍酸梅，正一边剥花生一边冲楼下路过的杂耍班子挥手。","status":"approved"}]},{"name":"商镜寒","kind":"芳闻","publicName":"商镜寒","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-商镜寒-1","ordinal":1,"text":"附近客栈的大堂角落里，一身深色短袍的商镜寒正独自就着清水嚼面饼。这位年轻人神情格外沉静，随身的行囊搁在脚边，似乎正坐着等同行的脚夫结账。","status":"approved"},{"id":"芳闻-商镜寒-2","ordinal":2,"text":"镇外旧牌坊下的茶棚里，商镜寒正坐着歇凉。她面容冷峻、话极少，旁人上前问路她也只微微颔首，眼下正慢条斯理地用软布擦拭护腕上的尘土。","status":"approved"},{"id":"芳闻-商镜寒-3","ordinal":3,"text":"集市书摊前，被称为墨雷的商镜寒正翻阅几本地志残卷。她神色专注，指节轻敲着书页，正向摊主打听附近荒岭残冢的去向，暂时还没离开摊前。","status":"approved"},{"id":"芳闻-商镜寒-4","ordinal":4,"text":"附近古桥的青石栏杆旁，商镜寒正负手观望桥下流水。她周身气度内敛，几个行脚僧路过合十行礼，她也客气回了一礼，眼下仍在桥头迎风静立。","status":"approved"}]},{"name":"白悟","kind":"芳闻","publicName":"白悟","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-白悟-1","ordinal":1,"text":"附近告示栏底下，白发蓝眸的散客白悟正仰头扯下一张除盗榜文。她一身粗布短打，利落地卷着袖口，正爽快地跟巡街差役核对赏银，这会儿正往怀里揣回执凭证。","status":"approved"},{"id":"芳闻-白悟-2","ordinal":2,"text":"镇口面摊前，白悟正稀里哗啦大口吃着臊子面，一头白发束得利落。她边吃边向面摊掌柜打听附近有没有油腔滑调的游方道士，看来还得再坐上一碗面的工夫。","status":"approved"}]},{"name":"秦施思","kind":"芳闻","publicName":"秦施思","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-秦施思-1","ordinal":1,"text":"附近大榕树下的卦摊前，游方术士秦施思正摇着幌子给人摸骨看相。她三寸不烂之舌极是厉害，把对面的行商说得连连点头，这会儿正乐呵呵地把卦金往袖里收。","status":"approved"},{"id":"芳闻-秦施思-2","ordinal":2,"text":"巷口茶馆里，秦施思正倚在柜台边与武林盟的信差勾肩搭背套近乎。她一身半旧道袍，满脸堆笑，正悄悄打听哪条出镇的路没白发散客把守，手里的茶碗还没放下。","status":"approved"}]},{"name":"凌寒舞","kind":"芳闻","publicName":"凌寒舞","enabled":true,"public":true,"province":"跨域池","scope":"跨域池","rumors":[{"id":"芳闻-凌寒舞-1","ordinal":1,"text":"听村口布庄的伙计讲，那位白发蓝眸的凌寒舞姑娘正站在铺子前挑新裁的云纹罗裙呢。嘴上直挑剔料子不够轻软，手却舍不得放下，这会儿还在镜子前比划着不肯走。","status":"approved"},{"id":"芳闻-凌寒舞-2","ordinal":2,"text":"附近山脚下的茶摊阿婆笑说，刚来歇脚的凌寒舞姑娘嘴硬得很，一边嚷着山路石子硌脚再不来了，一边却坐着帮她挑拣刚摘的野果，这会儿正捧着粗陶碗吹凉茶呢。","status":"approved"}]},{"name":"铁拐李","kind":"恶闻","publicName":"铁拐李","enabled":true,"public":true,"province":"十大恶人","scope":"主角附近","rumors":[{"id":"恶闻-铁拐李-1","ordinal":1,"text":"有人低声说，附近来了个披旧僧袍的瘸腿老汉，正拄着骷髅铁拐嚼冷饼。那张脸和铁拐李的传形颇像，旁人想多看两眼，便被他冷冷扫了回来，此刻还没走远。","status":"approved"},{"id":"恶闻-铁拐李-2","ordinal":2,"text":"刚有人在近处瞧见铁拐李，正拿块粗石磨那根骷髅铁拐。铁屑落了一地，他却磨得不紧不慢，听见有人提官府的赏格，忽然停手朝说话的人望了过去。","status":"approved"}]},{"name":"曹国舅","kind":"恶闻","publicName":"曹国舅","enabled":true,"public":true,"province":"十大恶人","scope":"主角附近","rumors":[{"id":"恶闻-曹国舅-1","ordinal":1,"text":"近处有人见着一位自称曹国舅的美髯客，玉色长袍、龙纹玉佩，正慢条斯理挑几匹锦料。旁人认出凶名，连讨价还价都低了声，他倒仍催着人再拿好货来。","status":"approved"},{"id":"恶闻-曹国舅-2","ordinal":2,"text":"听人悄声议论，曹国舅眼下就在附近歇脚，正独自品茶，折扇轻摇。有人不慎提起朝廷，他便抬眼打量那人，笑着问是哪家衙门的消息，问完也不急着离开。","status":"approved"}]},{"name":"汉钟离","kind":"恶闻","publicName":"汉钟离","enabled":true,"public":true,"province":"十大恶人","scope":"主角附近","rumors":[{"id":"恶闻-汉钟离-1","ordinal":1,"text":"附近几个行脚人正避着一个喝酒的高大汉子。那人脸带横疤、穿着旧军袍，正抱坛痛饮，有人认出是汉钟离，话还没说完便缩了脖子，连自己的酒都不要了。","status":"approved"},{"id":"恶闻-汉钟离-2","ordinal":2,"text":"有人说汉钟离眼下就在近处歇着，残酒搁在手边，鼾声响得惊人。一名过路人踢翻了酒坛，他已睁眼撑起身子，正盯着那人伸手讨酒钱，四下顿时没人出声。","status":"approved"}]},{"name":"吕洞宾","kind":"恶闻","publicName":"吕洞宾","enabled":true,"public":true,"province":"十大恶人","scope":"主角附近","rumors":[{"id":"恶闻-吕洞宾-1","ordinal":1,"text":"附近有人正看一位青衫长髯客与人论旧书，言辞斯文，颇有鸿儒气度。认出吕洞宾的人却悄悄退开了几步；他仍摇着折扇谈笑，正请那位卖书人把残页展开。","status":"approved"},{"id":"恶闻-吕洞宾-2","ordinal":2,"text":"听闻青衫客吕洞宾此刻正在附近暂歇，白玉折扇压着一册旧书，正吩咐人添茶。几个识得他的江湖客远远停下，既不敢上前，也舍不得放过这条赏格的风声。","status":"approved"}]},{"name":"拓跋秉我","kind":"恶闻","publicName":"拓跋秉我","enabled":true,"public":true,"province":"十大恶人","scope":"主角附近","rumors":[{"id":"恶闻-拓跋秉我-1","ordinal":1,"text":"附近刚有人瞧见一名猩红衣袍的女子，赤发赤瞳，正警惕地打量来往的人。有人认出血龙君拓跋秉我，吓得当即退回；她还留在近处，指尖一下下敲着膝头。","status":"approved"},{"id":"恶闻-拓跋秉我-2","ordinal":2,"text":"有人压低嗓子传信，拓跋秉我眼下就在附近，正低头擦拭尖锐的指甲。听见长乐帮三个字，她忽地抬了头，盯住说话的方向，连原本想挪步的人都僵在了原处。","status":"approved"},{"id":"恶闻-拓跋秉我-3","ordinal":3,"text":"近处有个赤发女子正独自歇着，对旁人的招呼一声不应。行脚人认出是拓跋秉我，忙劝同伴绕开；她却像听见了似的，抬眼逐一打量那些行囊，此刻并未离去。","status":"approved"}]},{"name":"张果老","kind":"恶闻","publicName":"张果老","enabled":true,"public":true,"province":"十大恶人","scope":"主角附近","rumors":[{"id":"恶闻-张果老-1","ordinal":1,"text":"附近有人瞧见张果老倒骑着一头瘸驴，药箱挂在两侧，正慢悠悠往这边来。他嘴里哼着怪调，问人要不要买药，认得那张老脸的人却连连摆手，往旁边让出老远。","status":"approved"},{"id":"恶闻-张果老-2","ordinal":2,"text":"张果老眼下正在附近摊开药箱挑拣草根，一副游方郎中的模样。有人上前问价，他便笑着招手让对方凑近些；旁边认出他的人脸色一变，正悄悄扯那人的袖子。","status":"approved"}]},{"name":"蓝采和","kind":"恶闻","publicName":"蓝采和","enabled":true,"public":true,"province":"十大恶人","scope":"主角附近","rumors":[{"id":"恶闻-蓝采和-1","ordinal":1,"text":"听人说，蓝采和此刻正在近处喝粗茶，旧青衫洗得泛白，手里摆弄着几根算筹。有人认出凶名，话音忽然低了；他却像没听见，仍请人替他再添一碗热的。","status":"approved"},{"id":"恶闻-蓝采和-2","ordinal":2,"text":"附近有人见着一位俊朗的青衫客，正同卖货人慢慢还价，言语清高却分文不让。有人认出是蓝采和，围观的人便往后退了退，他仍站在原处，细挑货物上的瑕疵。","status":"approved"}]},{"name":"何仙姑","kind":"恶闻","publicName":"何仙姑","enabled":true,"public":true,"province":"十大恶人","scope":"主角附近","rumors":[{"id":"恶闻-何仙姑-1","ordinal":1,"text":"有人低声说，何仙姑眼下就在附近，一身素衣，臂上缠着赤绸，正静静打量来往行人。有人无意间露出官差腰牌，她的目光便停住了，那人正慌忙把牌子往怀里收。","status":"approved"},{"id":"恶闻-何仙姑-2","ordinal":2,"text":"近处有人瞧见何仙姑独自暂歇，素髻白衣，手中正慢慢理着那条赤色绸带。一个行脚人认出了她，连忙提醒同伴别提衙门的差事；她抬头看了一眼，仍未起身。","status":"approved"},{"id":"恶闻-何仙姑-3","ordinal":3,"text":"附近几个过路人正在悄悄议论一名独坐的白衣女子，说像是何仙姑。她臂缠赤绸，正端碗吹去茶沫，听见远处有人谈官府押解，忽然把碗放下，侧耳听了起来。","status":"approved"}]},{"name":"韩湘子","kind":"恶闻","publicName":"韩湘子","enabled":true,"public":true,"province":"十大恶人","scope":"主角附近","rumors":[{"id":"恶闻-韩湘子-1","ordinal":1,"text":"附近有人瞧见一名穿书生衣衫的清俊游方客，手里倒插一管碧玉箫，正笑着向人打听热闹。他的玉箫与追索韩湘子的案卷所记颇像，报信的人已悄悄动身，他还在原处。","status":"approved"},{"id":"恶闻-韩湘子-2","ordinal":2,"text":"近处一位持玉箫的白面公子正挑仕女折扇，与卖货人谈笑还价。旁人说那管箫像是韩湘子案卷里提过的物件，却没人敢凭一眼认定；他仍翻着扇面，迟迟没有选定。","status":"approved"}]},{"name":"金醴","kind":"芳闻","publicName":"金醴","enabled":true,"public":true,"province":"大凉通用池","scope":"大凉通用池","rumors":[{"id":"芳闻-金醴-1","ordinal":1,"text":"西街酒肆临街的柳树杈上，那位身着半截月白道袍的金醴姑娘正斜倚着枝桠晃荡双腿呢。她单用一根竹筷挽着乌发，微醺着半眯起勾人的桃花眼，正仰头往嘴里倒红玉葫芦里的烈酒，嘴里还嘟囔着人间大醉方才快活。","status":"approved"},{"id":"芳闻-金醴-2","ordinal":2,"text":"城东热闹的瓦子集市旁，腰束朱红粗绳的金醴姑娘正摆摊卖字画呢。她盘缠见底却不见慌乱，一手按着刻了“醉”字的杜康剑，一手拎笔挥毫泼洒狂草，墨香混着满身浓烈酒气，引得过往游侠书生围了一整圈拍手叫绝。","status":"approved"}]},{"name":"沈轻茗","kind":"芳闻","publicName":"沈轻茗","enabled":true,"public":true,"province":"岳州","scope":"岳州","rumors":[{"id":"芳闻-沈轻茗-1","ordinal":1,"text":"巴陵城演武楼分部的廊下摞着几篓旧书，一身宽大白衣的沈轻茗正逐页验看。有人拿了本缺头少尾的拳谱来换银子，她才翻过两页，便指出抄本把运劲次序写反了。那人还想争辩，她把书搁回案上，让他照着原句再读一遍。","status":"approved"},{"id":"芳闻-沈轻茗-2","ordinal":2,"text":"巴陵城茶楼里，几名江湖客正争论新一期人榜。沈轻茗抱着雪兔摇光坐在临窗的位置，听到有人把两位剑客的胜负说反，便放下茶盏，一一指出双方换招时的破绽。争论的人越围越多，她却只问掌柜能否再添一碟点心。","status":"approved"}]},{"name":"罗猫猫","kind":"芳闻","publicName":"罗猫猫","enabled":true,"public":true,"province":"高丽","scope":"高丽","rumors":[{"id":"芳闻-罗猫猫-1","ordinal":1,"text":"汉阳城宫门外，有人见那满脸雀斑的小医女把药包抱得比午饭还紧。摊主多送了一小把干药，她便蹲在摊边，替他把看不懂的药材标签逐一认了。","status":"approved"},{"id":"芳闻-罗猫猫-2","ordinal":2,"text":"花街的姐姐们说，罗猫猫进宫当差后仍常回来，带的总是药膏和零嘴。谁若咳嗽两声，她嘴上嫌人吵，手里已经把脉枕从包底翻了出来。","status":"approved"},{"id":"芳闻-罗猫猫-3","ordinal":3,"text":"宫中药房近日又有人找那位罗姓助手配药。她顶着几颗画歪的雀斑，先问是哪味药煎错了时辰，再慢悠悠起身；旁人催得急，她还要先把手边药罐盖严。","status":"approved"}]}]});
